('617','inventarios_retroactivos_pmp','-- =============================================================================\r\n-- Motor cronologico de stock/PMP e inventarios retroactivos\r\n-- =============================================================================\r\n-- El motor trabaja con la tabla temporal tmp_movimientos_recalculo. Cada\r\n-- clave conserva el primer instante afectado y respeta la transaccion del\r\n-- llamante. AE solo se conserva como compatibilidad historica.\r\n\r\nDELIMITER ;;\r\nDROP PROCEDURE IF EXISTS tmp_invlin_pmp_corregido;;\r\nCREATE PROCEDURE tmp_invlin_pmp_corregido()\r\nBEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1\r\n      FROM information_schema.COLUMNS\r\n     WHERE TABLE_SCHEMA = DATABASE()\r\n       AND TABLE_NAME = \'fza_inventarios_lineas\'\r\n       AND COLUMN_NAME = \'ESPRECIO_MEDIO_CORREGIDO_INVLIN\'\r\n  ) THEN\r\n    ALTER TABLE fza_inventarios_lineas\r\n      ADD COLUMN ESPRECIO_MEDIO_CORREGIDO_INVLIN varchar(1)\r\n      NOT NULL DEFAULT \'N\'\r\n      COMMENT \'S si el PMP nuevo fue indicado expresamente\';\r\n  END IF;\r\nEND;;\r\nDELIMITER ;\r\nCALL tmp_invlin_pmp_corregido();\r\nDROP PROCEDURE tmp_invlin_pmp_corregido;\r\n\r\nDELIMITER ;;\r\nDROP PROCEDURE IF EXISTS tmp_mov_linea_ampliar;;\r\nCREATE PROCEDURE tmp_mov_linea_ampliar()\r\nBEGIN\r\n  IF EXISTS (\r\n    SELECT 1\r\n      FROM information_schema.COLUMNS\r\n     WHERE TABLE_SCHEMA = DATABASE()\r\n       AND TABLE_NAME = \'fza_movimientos_almacen\'\r\n       AND COLUMN_NAME = \'LINEA_MOV\'\r\n       AND CHARACTER_MAXIMUM_LENGTH < 10\r\n  ) THEN\r\n    ALTER TABLE fza_movimientos_almacen\r\n      MODIFY COLUMN LINEA_MOV varchar(10) NOT NULL\r\n      COMMENT \'Linea del documento origen\';\r\n  END IF;\r\nEND;;\r\nDELIMITER ;\r\nCALL tmp_mov_linea_ampliar();\r\nDROP PROCEDURE tmp_mov_linea_ampliar;\r\n\r\n-- Los inventarios aplicados por versiones anteriores podian tener una sola\r\n-- pata. Se completa el par para que el recuento siga siendo un cierre fisico.\r\nINSERT IGNORE INTO fza_movimientos_almacen\r\n  (NUMERO_MOV, TIPO_DOC_MOV, SERIE_DOC_MOV, NUMERO_DOC_MOV, LINEA_MOV,\r\n   CODIGO_EMP_MOV, CODIGO_ALM_MOV, FECHA_MOV, CODIGO_ART_MOV,\r\n   CODIGO_UNIDAD_MOV, DESCRIPCION_ARTICULO_MOV, TIPO_MOV, CANTIDAD_MOV,\r\n   PRECIO_COSTE_UNITARIO_MOV, TOTAL_COSTE_MOV, PRECIO_MEDIO_MOV,\r\n   CODIGO_ALM_CONTRA_MOV, CODIGO_CLI_MOV, CODIGO_PRV_MOV, ESACTIVO_MOV,\r\n   INSTANTE_MODIF, INSTANTE_ALTA, USUARIO_ALTA, USUARIO_MODIF,\r\n   TIPO_DOC_REF_MOV, SERIE_DOC_REF_MOV, NUMERO_DOC_REF_MOV, LINEA_REF_MOV,\r\n   LOTE_MOV, FECHA_CADUCIDAD_MOV, CODIGO_ALM_DOC_MOV,\r\n   NUMERO_OPERACION_DOC_MOV, CODIGO_CAJA_DOC_MOV)\r\nSELECT CONCAT(\'IVS\', LEFT(SHA2(CONCAT_WS(CHAR(31),\r\n         l.CODIGO_EMP_INVLIN, l.CODIGO_ALM_INVLIN, l.SERIE_INV_INVLIN,\r\n         l.NUMERO_INV_INVLIN, l.LINEA_INVLIN), 256), 17)),\r\n       \'IN\', l.SERIE_INV_INVLIN, l.NUMERO_INV_INVLIN, l.LINEA_INVLIN,\r\n       l.CODIGO_EMP_INVLIN, l.CODIGO_ALM_INVLIN,\r\n       DATE_SUB(IFNULL(l.FECHA_RECUENTO_INVLIN,\r\n         TIMESTAMP(DATE_SUB(DATE(i.FECHA_INV), INTERVAL 1 DAY), \'23:59:59\')),\r\n         INTERVAL 1 SECOND),\r\n       l.CODIGO_ART_INVLIN, l.CODIGO_UNIDAD_INVLIN,\r\n       l.DESCRIPCION_ARTICULO_INVLIN, \'S\',\r\n       IFNULL(l.CANTIDAD_TEORICA_INVLIN, 0),\r\n       IFNULL(l.PRECIO_MEDIO_INVLIN, 0),\r\n       IFNULL(l.CANTIDAD_TEORICA_INVLIN, 0) *\r\n         IFNULL(l.PRECIO_MEDIO_INVLIN, 0),\r\n       IFNULL(l.PRECIO_MEDIO_INVLIN, 0), NULL, NULL, NULL, \'S\',\r\n       NOW(), NOW(), l.USUARIO_ALTA, l.USUARIO_MODIF,\r\n       NULL, NULL, NULL, NULL, \'\', NULL, l.CODIGO_ALM_INVLIN,\r\n       NULL, NULL\r\n  FROM fza_inventarios_lineas l\r\n  JOIN fza_inventarios i\r\n    ON i.CODIGO_EMP_INV = l.CODIGO_EMP_INVLIN\r\n   AND i.CODIGO_ALM_INV = l.CODIGO_ALM_INVLIN\r\n   AND i.SERIE_INV = l.SERIE_INV_INVLIN\r\n   AND i.NUMERO_INV = l.NUMERO_INV_INVLIN\r\n  JOIN fza_movimientos_almacen e\r\n    ON e.TIPO_DOC_MOV = \'IN\'\r\n   AND e.TIPO_MOV = \'E\'\r\n   AND e.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN\r\n   AND e.SERIE_DOC_MOV = l.SERIE_INV_INVLIN\r\n   AND e.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN\r\n   AND CAST(e.LINEA_MOV AS UNSIGNED) = CAST(l.LINEA_INVLIN AS UNSIGNED)\r\n WHERE i.ESTADO_INV = \'APLICADO\'\r\n   AND NOT EXISTS (\r\n     SELECT 1\r\n       FROM fza_movimientos_almacen s\r\n      WHERE s.TIPO_DOC_MOV = \'IN\'\r\n        AND s.TIPO_MOV = \'S\'\r\n        AND s.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN\r\n        AND s.SERIE_DOC_MOV = l.SERIE_INV_INVLIN\r\n        AND s.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN\r\n        AND CAST(s.LINEA_MOV AS UNSIGNED) =\r\n            CAST(l.LINEA_INVLIN AS UNSIGNED));\r\n\r\nINSERT IGNORE INTO fza_movimientos_almacen\r\n  (NUMERO_MOV, TIPO_DOC_MOV, SERIE_DOC_MOV, NUMERO_DOC_MOV, LINEA_MOV,\r\n   CODIGO_EMP_MOV, CODIGO_ALM_MOV, FECHA_MOV, CODIGO_ART_MOV,\r\n   CODIGO_UNIDAD_MOV, DESCRIPCION_ARTICULO_MOV, TIPO_MOV, CANTIDAD_MOV,\r\n   PRECIO_COSTE_UNITARIO_MOV, TOTAL_COSTE_MOV, PRECIO_MEDIO_MOV,\r\n   CODIGO_ALM_CONTRA_MOV, CODIGO_CLI_MOV, CODIGO_PRV_MOV, ESACTIVO_MOV,\r\n   INSTANTE_MODIF, INSTANTE_ALTA, USUARIO_ALTA, USUARIO_MODIF,\r\n   TIPO_DOC_REF_MOV, SERIE_DOC_REF_MOV, NUMERO_DOC_REF_MOV, LINEA_REF_MOV,\r\n   LOTE_MOV, FECHA_CADUCIDAD_MOV, CODIGO_ALM_DOC_MOV,\r\n   NUMERO_OPERACION_DOC_MOV, CODIGO_CAJA_DOC_MOV)\r\nSELECT CONCAT(\'IVE\', LEFT(SHA2(CONCAT_WS(CHAR(31),\r\n         l.CODIGO_EMP_INVLIN, l.CODIGO_ALM_INVLIN, l.SERIE_INV_INVLIN,\r\n         l.NUMERO_INV_INVLIN, l.LINEA_INVLIN), 256), 17)),\r\n       \'IN\', l.SERIE_INV_INVLIN, l.NUMERO_INV_INVLIN, l.LINEA_INVLIN,\r\n       l.CODIGO_EMP_INVLIN, l.CODIGO_ALM_INVLIN,\r\n       IFNULL(l.FECHA_RECUENTO_INVLIN,\r\n         TIMESTAMP(DATE_SUB(DATE(i.FECHA_INV), INTERVAL 1 DAY), \'23:59:59\')),\r\n       l.CODIGO_ART_INVLIN, l.CODIGO_UNIDAD_INVLIN,\r\n       l.DESCRIPCION_ARTICULO_INVLIN, \'E\',\r\n       IFNULL(l.CANTIDAD_FISICA_INVLIN, 0),\r\n       IFNULL(l.PRECIO_MEDIO_NUEVO_INVLIN, 0),\r\n       IFNULL(l.CANTIDAD_FISICA_INVLIN, 0) *\r\n         IFNULL(l.PRECIO_MEDIO_NUEVO_INVLIN, 0),\r\n       IFNULL(l.PRECIO_MEDIO_NUEVO_INVLIN, 0), NULL, NULL, NULL, \'S\',\r\n       NOW(), NOW(), l.USUARIO_ALTA, l.USUARIO_MODIF,\r\n       NULL, NULL, NULL, NULL, \'\', NULL, l.CODIGO_ALM_INVLIN,\r\n       NULL, NULL\r\n  FROM fza_inventarios_lineas l\r\n  JOIN fza_inventarios i\r\n    ON i.CODIGO_EMP_INV = l.CODIGO_EMP_INVLIN\r\n   AND i.CODIGO_ALM_INV = l.CODIGO_ALM_INVLIN\r\n   AND i.SERIE_INV = l.SERIE_INV_INVLIN\r\n   AND i.NUMERO_INV = l.NUMERO_INV_INVLIN\r\n  JOIN fza_movimientos_almacen s\r\n    ON s.TIPO_DOC_MOV = \'IN\'\r\n   AND s.TIPO_MOV = \'S\'\r\n   AND s.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN\r\n   AND s.SERIE_DOC_MOV = l.SERIE_INV_INVLIN\r\n   AND s.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN\r\n   AND CAST(s.LINEA_MOV AS UNSIGNED) = CAST(l.LINEA_INVLIN AS UNSIGNED)\r\n WHERE i.ESTADO_INV = \'APLICADO\'\r\n   AND NOT EXISTS (\r\n     SELECT 1\r\n       FROM fza_movimientos_almacen e\r\n      WHERE e.TIPO_DOC_MOV = \'IN\'\r\n        AND e.TIPO_MOV = \'E\'\r\n        AND e.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN\r\n        AND e.SERIE_DOC_MOV = l.SERIE_INV_INVLIN\r\n        AND e.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN\r\n        AND CAST(e.LINEA_MOV AS UNSIGNED) =\r\n            CAST(l.LINEA_INVLIN AS UNSIGNED));\r\n\r\nUPDATE fza_inventarios_lineas l\r\n  JOIN fza_inventarios i\r\n    ON i.CODIGO_EMP_INV = l.CODIGO_EMP_INVLIN\r\n   AND i.CODIGO_ALM_INV = l.CODIGO_ALM_INVLIN\r\n   AND i.SERIE_INV = l.SERIE_INV_INVLIN\r\n   AND i.NUMERO_INV = l.NUMERO_INV_INVLIN\r\n   SET l.ESPRECIO_MEDIO_CORREGIDO_INVLIN =\r\n       IF(ABS(IFNULL(l.PRECIO_MEDIO_NUEVO_INVLIN, 0) -\r\n              IFNULL(l.PRECIO_MEDIO_INVLIN, 0)) > 0.0000005, \'S\', \'N\')\r\n WHERE i.ESTADO_INV = \'ABIERTO\';\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR`()\r\nBEGIN\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo;\r\n  CREATE TEMPORARY TABLE tmp_movimientos_recalculo (\r\n    empresa varchar(20) NOT NULL DEFAULT \'\',\r\n    almacen varchar(10) NOT NULL,\r\n    sku varchar(50) NOT NULL,\r\n    instante_desde datetime NOT NULL,\r\n    PRIMARY KEY (almacen, sku)\r\n  ) ENGINE=InnoDB;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR`(\r\n  IN p_EMPRESA varchar(20),\r\n  IN p_ALMACEN varchar(10),\r\n  IN p_SKU varchar(50),\r\n  IN p_INSTANTE_DESDE datetime\r\n)\r\nBEGIN\r\n  IF IFNULL(p_ALMACEN, \'\') <> \'\' AND IFNULL(p_SKU, \'\') <> \'\' THEN\r\n    INSERT INTO tmp_movimientos_recalculo\r\n      (empresa, almacen, sku, instante_desde)\r\n    VALUES\r\n      (IFNULL(p_EMPRESA, \'\'), p_ALMACEN, p_SKU,\r\n       IFNULL(p_INSTANTE_DESDE, \'1000-01-01 00:00:00\'))\r\n    ON DUPLICATE KEY UPDATE\r\n      empresa = IF(empresa = \'\', VALUES(empresa), empresa),\r\n      instante_desde = LEAST(instante_desde, VALUES(instante_desde));\r\n  END IF;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO`(\r\n  IN p_TIPO varchar(5),\r\n  IN p_SERIE varchar(20),\r\n  IN p_NUMERO varchar(20)\r\n)\r\nBEGIN\r\n  INSERT INTO tmp_movimientos_recalculo\r\n    (empresa, almacen, sku, instante_desde)\r\n  SELECT MIN(IFNULL(CODIGO_EMP_MOV, \'\')),\r\n         CODIGO_ALM_MOV,\r\n         CODIGO_UNIDAD_MOV,\r\n         MIN(IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\'))\r\n    FROM fza_movimientos_almacen\r\n   WHERE TIPO_DOC_MOV = p_TIPO\r\n     AND SERIE_DOC_MOV = p_SERIE\r\n     AND NUMERO_DOC_MOV = p_NUMERO\r\n   GROUP BY CODIGO_ALM_MOV, CODIGO_UNIDAD_MOV\r\n  ON DUPLICATE KEY UPDATE\r\n    empresa = IF(empresa = \'\', VALUES(empresa), empresa),\r\n    instante_desde = LEAST(instante_desde, VALUES(instante_desde));\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_OPERACION`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_OPERACION`(\r\n  IN p_OPERACION varchar(20)\r\n)\r\nBEGIN\r\n  INSERT INTO tmp_movimientos_recalculo\r\n    (empresa, almacen, sku, instante_desde)\r\n  SELECT MIN(IFNULL(CODIGO_EMP_MOV, \'\')),\r\n         CODIGO_ALM_MOV,\r\n         CODIGO_UNIDAD_MOV,\r\n         MIN(IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\'))\r\n    FROM fza_movimientos_almacen\r\n   WHERE NUMERO_OPERACION_DOC_MOV = p_OPERACION\r\n   GROUP BY CODIGO_ALM_MOV, CODIGO_UNIDAD_MOV\r\n  ON DUPLICATE KEY UPDATE\r\n    empresa = IF(empresa = \'\', VALUES(empresa), empresa),\r\n    instante_desde = LEAST(instante_desde, VALUES(instante_desde));\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR_COLA`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR_COLA`()\r\nBEGIN\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_recalculo_semillas;\r\n  CREATE TEMPORARY TABLE tmp_recalculo_semillas (\r\n    almacen varchar(10) NOT NULL,\r\n    sku varchar(50) NOT NULL,\r\n    instante_desde datetime NOT NULL,\r\n    stock_semilla decimal(19,6) NOT NULL DEFAULT 0,\r\n    pmp_semilla decimal(19,6) NOT NULL DEFAULT 0,\r\n    PRIMARY KEY (almacen, sku)\r\n  ) ENGINE=InnoDB;\r\n  INSERT INTO tmp_recalculo_semillas\r\n    (almacen, sku, instante_desde, stock_semilla)\r\n  SELECT r.almacen,\r\n         r.sku,\r\n         r.instante_desde,\r\n         IFNULL(SUM(IF(m.TIPO_MOV = \'E\', m.CANTIDAD_MOV,\r\n                                         -m.CANTIDAD_MOV)), 0)\r\n    FROM tmp_movimientos_recalculo r\r\n    LEFT JOIN fza_movimientos_almacen m\r\n      ON m.CODIGO_ALM_MOV = r.almacen\r\n     AND m.CODIGO_UNIDAD_MOV = r.sku\r\n     AND m.ESACTIVO_MOV = \'S\'\r\n     AND IFNULL(m.FECHA_MOV, \'1000-01-01 00:00:00\') < r.instante_desde\r\n   GROUP BY r.almacen, r.sku, r.instante_desde;\r\n  UPDATE tmp_recalculo_semillas s\r\n     SET s.pmp_semilla = IFNULL((\r\n       SELECT m.PRECIO_MEDIO_MOV\r\n         FROM fza_movimientos_almacen m\r\n        WHERE m.CODIGO_ALM_MOV = s.almacen\r\n          AND m.CODIGO_UNIDAD_MOV = s.sku\r\n          AND m.ESACTIVO_MOV = \'S\'\r\n          AND IFNULL(m.FECHA_MOV, \'1000-01-01 00:00:00\') <\r\n              s.instante_desde\r\n        ORDER BY IFNULL(m.FECHA_MOV, \'1000-01-01 00:00:00\') DESC,\r\n                 IFNULL(m.INSTANTE_ALTA, \'1000-01-01 00:00:00\') DESC,\r\n                 m.NUMERO_MOV DESC\r\n        LIMIT 1), 0);\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_ordenados;\r\n  CREATE TEMPORARY TABLE tmp_movimientos_ordenados (\r\n    rn bigint NOT NULL AUTO_INCREMENT,\r\n    numero_mov varchar(20) NOT NULL,\r\n    almacen varchar(10) NOT NULL,\r\n    sku varchar(50) NOT NULL,\r\n    clave varchar(101) NOT NULL,\r\n    tipo_doc varchar(5) NOT NULL,\r\n    tipo_mov varchar(1) NOT NULL,\r\n    cantidad decimal(19,6) NOT NULL,\r\n    coste_unitario decimal(19,6) NOT NULL,\r\n    es_cierre_inventario varchar(1) NOT NULL DEFAULT \'N\',\r\n    es_pmp_manual varchar(1) NOT NULL DEFAULT \'N\',\r\n    stock_semilla decimal(19,6) NOT NULL,\r\n    pmp_semilla decimal(19,6) NOT NULL,\r\n    stock_nuevo decimal(19,6) NOT NULL DEFAULT 0,\r\n    pmp_nuevo decimal(19,6) NOT NULL DEFAULT 0,\r\n    coste_nuevo decimal(19,6) NOT NULL DEFAULT 0,\r\n    clave_previa varchar(101) NULL,\r\n    PRIMARY KEY (rn),\r\n    KEY idx_movimiento (numero_mov),\r\n    KEY idx_clave (almacen, sku)\r\n  ) ENGINE=InnoDB;\r\n  INSERT INTO tmp_movimientos_ordenados\r\n    (numero_mov, almacen, sku, clave, tipo_doc, tipo_mov, cantidad,\r\n     coste_unitario, es_cierre_inventario, es_pmp_manual,\r\n     stock_semilla, pmp_semilla)\r\n  SELECT m.NUMERO_MOV,\r\n         m.CODIGO_ALM_MOV,\r\n         m.CODIGO_UNIDAD_MOV,\r\n         CONCAT(m.CODIGO_ALM_MOV, CHAR(31), m.CODIGO_UNIDAD_MOV),\r\n         m.TIPO_DOC_MOV,\r\n         m.TIPO_MOV,\r\n         IFNULL(m.CANTIDAD_MOV, 0),\r\n         IFNULL(m.PRECIO_COSTE_UNITARIO_MOV, 0),\r\n         IF(i.NUMERO_INV IS NULL, \'N\', \'S\'),\r\n         IFNULL(l.ESPRECIO_MEDIO_CORREGIDO_INVLIN, \'N\'),\r\n         s.stock_semilla,\r\n         s.pmp_semilla\r\n    FROM fza_movimientos_almacen m\r\n    JOIN tmp_recalculo_semillas s\r\n     ON s.almacen = m.CODIGO_ALM_MOV\r\n     AND s.sku = m.CODIGO_UNIDAD_MOV\r\n    LEFT JOIN fza_inventarios i\r\n      ON m.TIPO_DOC_MOV = \'IN\'\r\n     AND i.CODIGO_ALM_INV = m.CODIGO_ALM_MOV\r\n     AND i.SERIE_INV = m.SERIE_DOC_MOV\r\n     AND i.NUMERO_INV = m.NUMERO_DOC_MOV\r\n    LEFT JOIN fza_inventarios_lineas l\r\n      ON l.CODIGO_EMP_INVLIN = i.CODIGO_EMP_INV\r\n     AND l.CODIGO_ALM_INVLIN = i.CODIGO_ALM_INV\r\n     AND l.SERIE_INV_INVLIN = i.SERIE_INV\r\n     AND l.NUMERO_INV_INVLIN = i.NUMERO_INV\r\n     AND CAST(l.LINEA_INVLIN AS UNSIGNED) =\r\n         CAST(m.LINEA_MOV AS UNSIGNED)\r\n   WHERE m.ESACTIVO_MOV = \'S\'\r\n     AND IFNULL(m.FECHA_MOV, \'1000-01-01 00:00:00\') >= s.instante_desde\r\n   ORDER BY m.CODIGO_ALM_MOV,\r\n            m.CODIGO_UNIDAD_MOV,\r\n            IFNULL(m.FECHA_MOV, \'1000-01-01 00:00:00\'),\r\n            IFNULL(m.INSTANTE_ALTA, \'1000-01-01 00:00:00\'),\r\n            m.NUMERO_MOV;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_CALCULAR_COLA`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_CALCULAR_COLA`()\r\nBEGIN\r\n  SET @clave_previa := \'\';\r\n  SET @stock := CAST(0 AS DECIMAL(19,6));\r\n  SET @pmp := CAST(0 AS DECIMAL(19,6));\r\n  UPDATE tmp_movimientos_ordenados\r\n     SET cantidad = IF(es_cierre_inventario = \'S\' AND tipo_mov = \'S\',\r\n           IF(@clave_previa <> clave, stock_semilla, @stock), cantidad),\r\n         coste_unitario = IF(es_cierre_inventario = \'S\' AND\r\n                              tipo_mov = \'E\' AND es_pmp_manual <> \'S\',\r\n           IF(@clave_previa <> clave, pmp_semilla, @pmp), coste_unitario),\r\n         pmp_nuevo = (@pmp := IF(\r\n           @clave_previa <> clave,\r\n           IF(tipo_mov = \'E\',\r\n              IF(stock_semilla <= 0, coste_unitario,\r\n                 IF(stock_semilla + cantidad = 0, coste_unitario,\r\n                    ((stock_semilla * pmp_semilla) +\r\n                     (cantidad * coste_unitario)) /\r\n                    (stock_semilla + cantidad))),\r\n              pmp_semilla),\r\n           IF(tipo_mov = \'E\',\r\n              IF(@stock <= 0, coste_unitario,\r\n                 IF(@stock + cantidad = 0, coste_unitario,\r\n                    ((@stock * @pmp) + (cantidad * coste_unitario)) /\r\n                    (@stock + cantidad))),\r\n              @pmp))),\r\n         coste_nuevo = IF(tipo_mov = \'E\', cantidad * coste_unitario,\r\n                                           cantidad * @pmp),\r\n         stock_nuevo = (@stock := IF(\r\n           @clave_previa <> clave,\r\n           stock_semilla + IF(tipo_mov = \'E\', cantidad, -cantidad),\r\n           @stock + IF(tipo_mov = \'E\', cantidad, -cantidad))),\r\n         clave_previa = (@clave_previa := clave)\r\n   ORDER BY rn;\r\n  UPDATE fza_movimientos_almacen m\r\n  JOIN tmp_movimientos_ordenados o ON o.numero_mov = m.NUMERO_MOV\r\n     SET m.CANTIDAD_MOV = o.cantidad,\r\n         m.PRECIO_COSTE_UNITARIO_MOV = IF(\r\n           o.es_cierre_inventario = \'S\',\r\n           IF(o.tipo_mov = \'S\', o.pmp_nuevo, o.coste_unitario),\r\n           m.PRECIO_COSTE_UNITARIO_MOV),\r\n         m.PRECIO_MEDIO_MOV = o.pmp_nuevo,\r\n         m.TOTAL_COSTE_MOV = o.coste_nuevo,\r\n         m.INSTANTE_MODIF = NOW();\r\n  UPDATE fza_inventarios_lineas l\r\n  JOIN fza_inventarios i\r\n    ON i.CODIGO_EMP_INV = l.CODIGO_EMP_INVLIN\r\n   AND i.CODIGO_ALM_INV = l.CODIGO_ALM_INVLIN\r\n   AND i.SERIE_INV = l.SERIE_INV_INVLIN\r\n   AND i.NUMERO_INV = l.NUMERO_INV_INVLIN\r\n  JOIN fza_movimientos_almacen s\r\n    ON s.TIPO_DOC_MOV = \'IN\'\r\n   AND s.TIPO_MOV = \'S\'\r\n   AND s.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN\r\n   AND s.SERIE_DOC_MOV = l.SERIE_INV_INVLIN\r\n   AND s.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN\r\n   AND CAST(s.LINEA_MOV AS UNSIGNED) = CAST(l.LINEA_INVLIN AS UNSIGNED)\r\n  JOIN tmp_movimientos_ordenados o\r\n    ON o.numero_mov = s.NUMERO_MOV\r\n   AND o.es_cierre_inventario = \'S\'\r\n  LEFT JOIN fza_movimientos_almacen e\r\n    ON e.TIPO_DOC_MOV = \'IN\'\r\n   AND e.TIPO_MOV = \'E\'\r\n   AND e.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN\r\n   AND e.SERIE_DOC_MOV = l.SERIE_INV_INVLIN\r\n   AND e.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN\r\n   AND CAST(e.LINEA_MOV AS UNSIGNED) = CAST(l.LINEA_INVLIN AS UNSIGNED)\r\n     SET l.CANTIDAD_TEORICA_INVLIN = s.CANTIDAD_MOV,\r\n         l.PRECIO_MEDIO_INVLIN = s.PRECIO_MEDIO_MOV,\r\n         l.PRECIO_MEDIO_NUEVO_INVLIN = IF(\r\n           l.ESPRECIO_MEDIO_CORREGIDO_INVLIN = \'S\',\r\n           l.PRECIO_MEDIO_NUEVO_INVLIN,\r\n           IFNULL(e.PRECIO_COSTE_UNITARIO_MOV, s.PRECIO_MEDIO_MOV)),\r\n         l.CANTIDAD_DIFERENCIA_INVLIN =\r\n           l.CANTIDAD_FISICA_INVLIN - s.CANTIDAD_MOV,\r\n         l.TOTAL_COSTE_DIFERENCIA_INVLIN =\r\n           (l.CANTIDAD_FISICA_INVLIN * IF(\r\n             l.ESPRECIO_MEDIO_CORREGIDO_INVLIN = \'S\',\r\n             l.PRECIO_MEDIO_NUEVO_INVLIN,\r\n             IFNULL(e.PRECIO_COSTE_UNITARIO_MOV, s.PRECIO_MEDIO_MOV))) -\r\n           (s.CANTIDAD_MOV * s.PRECIO_MEDIO_MOV),\r\n         l.INSTANTE_MODIF = NOW()\r\n   WHERE i.ESTADO_INV = \'APLICADO\' OR i.ESTADO_INV = \'ABIERTO\';\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_ACTUALIZAR_STOCK`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_ACTUALIZAR_STOCK`()\r\nBEGIN\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_recalculo_final;\r\n  CREATE TEMPORARY TABLE tmp_recalculo_final (\r\n    almacen varchar(10) NOT NULL,\r\n    sku varchar(50) NOT NULL,\r\n    stock_final decimal(19,6) NOT NULL,\r\n    pmp_final decimal(19,6) NOT NULL,\r\n    PRIMARY KEY (almacen, sku)\r\n  ) ENGINE=InnoDB;\r\n  INSERT INTO tmp_recalculo_final\r\n    (almacen, sku, stock_final, pmp_final)\r\n  SELECT s.almacen,\r\n         s.sku,\r\n         IFNULL(o.stock_nuevo, s.stock_semilla),\r\n         IFNULL(o.pmp_nuevo, s.pmp_semilla)\r\n    FROM tmp_recalculo_semillas s\r\n    LEFT JOIN (\r\n      SELECT x.almacen, x.sku, x.stock_nuevo, x.pmp_nuevo\r\n        FROM tmp_movimientos_ordenados x\r\n        JOIN (\r\n          SELECT almacen, sku, MAX(rn) AS rn\r\n            FROM tmp_movimientos_ordenados\r\n           GROUP BY almacen, sku\r\n        ) u ON u.rn = x.rn\r\n    ) o ON o.almacen = s.almacen AND o.sku = s.sku;\r\n  INSERT INTO fza_articulos_stockactual\r\n    (CODIGO_ALM_STK, CODIGO_UNIDAD_STK, CANTIDAD_STK,\r\n     VALOR_TOTAL_STK, PRECIO_MEDIO_STK, INSTANTE_MODIF,\r\n     CANTIDAD_ENT_COMPRA_STK, CANTIDAD_ENT_TRASPASO_STK,\r\n     CANTIDAD_SAL_TRASPASO_STK, CANTIDAD_ENT_DEPOSITO_STK,\r\n     CANTIDAD_SAL_DEPOSITO_STK, CANTIDAD_SAL_VENTA_STK,\r\n     CANTIDAD_ENT_REGULAR_STK, CANTIDAD_SAL_ALBVENTA_STK,\r\n     CANTIDAD_ENT_ALBENTRADA_STK)\r\n  SELECT f.almacen,\r\n         f.sku,\r\n         f.stock_final,\r\n         IF(f.stock_final > 0, f.stock_final * f.pmp_final, 0),\r\n         IF(f.stock_final > 0, f.pmp_final, 0),\r\n         NOW(),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV = \'AC\' AND m.TIPO_MOV = \'E\',\r\n                       m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV IN (\'TR\', \'AT\', \'TA\') AND\r\n                       m.TIPO_MOV = \'E\', m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV IN (\'TR\', \'AT\', \'TA\') AND\r\n                       m.TIPO_MOV = \'S\', m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV = \'DP\' AND m.TIPO_MOV = \'E\',\r\n                       m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV = \'DP\' AND m.TIPO_MOV = \'S\',\r\n                       m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV IN (\'VE\', \'FC\') AND\r\n                       m.TIPO_MOV = \'S\', m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV = \'IN\' AND m.TIPO_MOV = \'E\',\r\n                       m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV = \'AV\' AND m.TIPO_MOV = \'S\',\r\n                       m.CANTIDAD_MOV, 0)), 0),\r\n         IFNULL(SUM(IF(m.TIPO_DOC_MOV = \'AE\' AND m.TIPO_MOV = \'E\',\r\n                       m.CANTIDAD_MOV, 0)), 0)\r\n    FROM tmp_recalculo_final f\r\n    LEFT JOIN fza_movimientos_almacen m\r\n      ON m.CODIGO_ALM_MOV = f.almacen\r\n     AND m.CODIGO_UNIDAD_MOV = f.sku\r\n     AND m.ESACTIVO_MOV = \'S\'\r\n   GROUP BY f.almacen, f.sku, f.stock_final, f.pmp_final\r\n  ON DUPLICATE KEY UPDATE\r\n    CANTIDAD_STK = VALUES(CANTIDAD_STK),\r\n    VALOR_TOTAL_STK = VALUES(VALOR_TOTAL_STK),\r\n    PRECIO_MEDIO_STK = VALUES(PRECIO_MEDIO_STK),\r\n    INSTANTE_MODIF = NOW(),\r\n    CANTIDAD_ENT_COMPRA_STK = VALUES(CANTIDAD_ENT_COMPRA_STK),\r\n    CANTIDAD_ENT_TRASPASO_STK = VALUES(CANTIDAD_ENT_TRASPASO_STK),\r\n    CANTIDAD_SAL_TRASPASO_STK = VALUES(CANTIDAD_SAL_TRASPASO_STK),\r\n    CANTIDAD_ENT_DEPOSITO_STK = VALUES(CANTIDAD_ENT_DEPOSITO_STK),\r\n    CANTIDAD_SAL_DEPOSITO_STK = VALUES(CANTIDAD_SAL_DEPOSITO_STK),\r\n    CANTIDAD_SAL_VENTA_STK = VALUES(CANTIDAD_SAL_VENTA_STK),\r\n    CANTIDAD_ENT_REGULAR_STK = VALUES(CANTIDAD_ENT_REGULAR_STK),\r\n    CANTIDAD_SAL_ALBVENTA_STK = VALUES(CANTIDAD_SAL_ALBVENTA_STK),\r\n    CANTIDAD_ENT_ALBENTRADA_STK = VALUES(CANTIDAD_ENT_ALBENTRADA_STK);\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_recalculo_final;\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_ordenados;\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_recalculo_semillas;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_PASADA`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_PASADA`()\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR_COLA();\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CALCULAR_COLA();\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_ACTUALIZAR_STOCK();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_PROPAGAR`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_PROPAGAR`(\r\n  OUT p_CAMBIOS int\r\n)\r\nBEGIN\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_traspasos_propagar;\r\n  CREATE TEMPORARY TABLE tmp_traspasos_propagar (\r\n    numero_entrada varchar(20) NOT NULL,\r\n    empresa varchar(20) NOT NULL,\r\n    almacen varchar(10) NOT NULL,\r\n    sku varchar(50) NOT NULL,\r\n    instante_desde datetime NOT NULL,\r\n    coste_salida decimal(19,6) NOT NULL,\r\n    PRIMARY KEY (numero_entrada)\r\n  ) ENGINE=InnoDB;\r\n  INSERT INTO tmp_traspasos_propagar\r\n    (numero_entrada, empresa, almacen, sku, instante_desde, coste_salida)\r\n  SELECT e.NUMERO_MOV,\r\n         IFNULL(e.CODIGO_EMP_MOV, \'\'),\r\n         e.CODIGO_ALM_MOV,\r\n         e.CODIGO_UNIDAD_MOV,\r\n         IFNULL(e.FECHA_MOV, \'1000-01-01 00:00:00\'),\r\n         SUM(s.TOTAL_COSTE_MOV) / NULLIF(SUM(s.CANTIDAD_MOV), 0)\r\n    FROM tmp_movimientos_recalculo r\r\n    JOIN fza_movimientos_almacen s\r\n      ON s.CODIGO_ALM_MOV = r.almacen\r\n     AND s.CODIGO_UNIDAD_MOV = r.sku\r\n     AND s.ESACTIVO_MOV = \'S\'\r\n     AND s.TIPO_DOC_MOV IN (\'TR\', \'AT\', \'TA\')\r\n     AND s.TIPO_MOV = \'S\'\r\n     AND IFNULL(s.FECHA_MOV, \'1000-01-01 00:00:00\') >= r.instante_desde\r\n    JOIN fza_movimientos_almacen e\r\n      ON e.TIPO_DOC_MOV = s.TIPO_DOC_MOV\r\n     AND e.SERIE_DOC_MOV = s.SERIE_DOC_MOV\r\n     AND e.NUMERO_DOC_MOV = s.NUMERO_DOC_MOV\r\n     AND e.CODIGO_UNIDAD_MOV = s.CODIGO_UNIDAD_MOV\r\n     AND e.CODIGO_ALM_MOV = s.CODIGO_ALM_CONTRA_MOV\r\n     AND e.CODIGO_ALM_CONTRA_MOV = s.CODIGO_ALM_MOV\r\n     AND e.ESACTIVO_MOV = \'S\'\r\n     AND e.TIPO_MOV = \'E\'\r\n     AND (e.LINEA_MOV = s.LINEA_MOV OR\r\n          (IFNULL(e.NUMERO_OPERACION_DOC_MOV, \'\') <> \'\' AND\r\n           e.NUMERO_OPERACION_DOC_MOV = s.NUMERO_OPERACION_DOC_MOV))\r\n   GROUP BY e.NUMERO_MOV, e.CODIGO_EMP_MOV, e.CODIGO_ALM_MOV,\r\n            e.CODIGO_UNIDAD_MOV, e.FECHA_MOV,\r\n            e.PRECIO_COSTE_UNITARIO_MOV\r\n  HAVING ABS(IFNULL(e.PRECIO_COSTE_UNITARIO_MOV, 0) -\r\n         (SUM(s.TOTAL_COSTE_MOV) / NULLIF(SUM(s.CANTIDAD_MOV), 0))) >\r\n         0.0000005;\r\n  SELECT COUNT(*) INTO p_CAMBIOS FROM tmp_traspasos_propagar;\r\n  UPDATE fza_movimientos_almacen e\r\n  JOIN tmp_traspasos_propagar p ON p.numero_entrada = e.NUMERO_MOV\r\n     SET e.PRECIO_COSTE_UNITARIO_MOV = p.coste_salida,\r\n         e.INSTANTE_MODIF = NOW();\r\n  DELETE FROM tmp_movimientos_recalculo;\r\n  INSERT INTO tmp_movimientos_recalculo\r\n    (empresa, almacen, sku, instante_desde)\r\n  SELECT MIN(empresa), almacen, sku, MIN(instante_desde)\r\n    FROM tmp_traspasos_propagar\r\n   GROUP BY almacen, sku;\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_traspasos_propagar;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR`()\r\nBEGIN\r\n  DECLARE v_CAMBIOS int DEFAULT 1;\r\n  DECLARE v_PASADAS int DEFAULT 0;\r\n  WHILE EXISTS(SELECT 1 FROM tmp_movimientos_recalculo) AND\r\n        v_CAMBIOS > 0 AND v_PASADAS < 100 DO\r\n    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PASADA();\r\n    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PROPAGAR(v_CAMBIOS);\r\n    SET v_PASADAS = v_PASADAS + 1;\r\n  END WHILE;\r\n  IF v_CAMBIOS > 0 THEN\r\n    SIGNAL SQLSTATE \'45000\'\r\n      SET MESSAGE_TEXT =\r\n        \'No converge la propagacion cronologica de traspasos\';\r\n  END IF;\r\n  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULAR_DOCUMENTO`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULAR_DOCUMENTO`(\r\n  IN p_TIPO varchar(5),\r\n  IN p_SERIE varchar(20),\r\n  IN p_NUMERO varchar(20)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO(\r\n    p_TIPO, p_SERIE, p_NUMERO);\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULAR_OPERACION`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULAR_OPERACION`(\r\n  IN p_OPERACION varchar(20)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_OPERACION(p_OPERACION);\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULAR_MOVIMIENTO`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULAR_MOVIMIENTO`(\r\n  IN p_NUMERO varchar(20)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  INSERT INTO tmp_movimientos_recalculo\r\n    (empresa, almacen, sku, instante_desde)\r\n  SELECT IFNULL(CODIGO_EMP_MOV, \'\'), CODIGO_ALM_MOV, CODIGO_UNIDAD_MOV,\r\n         IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\')\r\n    FROM fza_movimientos_almacen\r\n   WHERE NUMERO_MOV = p_NUMERO;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `SP_RECALCULAR_PMP_LOTE_ALMACEN`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `SP_RECALCULAR_PMP_LOTE_ALMACEN`(\r\n  IN p_EMPRESA varchar(20),\r\n  IN p_ALMACEN varchar(10)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  INSERT INTO tmp_movimientos_recalculo\r\n    (empresa, almacen, sku, instante_desde)\r\n  SELECT p_EMPRESA, p_ALMACEN, sku, \'1000-01-01 00:00:00\'\r\n    FROM tmp_skus_recalc;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `SP_RECALCULAR_PMP_SKU_ALMACEN`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `SP_RECALCULAR_PMP_SKU_ALMACEN`(\r\n  IN p_EMPRESA varchar(20),\r\n  IN p_SKU varchar(50),\r\n  IN p_ALMACEN varchar(10)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR(\r\n    p_EMPRESA, p_ALMACEN, p_SKU, \'1000-01-01 00:00:00\');\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_ALMACEN_DELETE`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_ALMACEN_DELETE`(\r\n  IN p_NUMERO_MOV varchar(20)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  INSERT INTO tmp_movimientos_recalculo\r\n    (empresa, almacen, sku, instante_desde)\r\n  SELECT IFNULL(CODIGO_EMP_MOV, \'\'), CODIGO_ALM_MOV, CODIGO_UNIDAD_MOV,\r\n         IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\')\r\n    FROM fza_movimientos_almacen\r\n   WHERE NUMERO_MOV = p_NUMERO_MOV;\r\n  DELETE FROM fza_movimientos_almacen WHERE NUMERO_MOV = p_NUMERO_MOV;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_ALMACEN_DELETE_DOC`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_ALMACEN_DELETE_DOC`(\r\n  IN p_TIPO varchar(5),\r\n  IN p_SERIE varchar(20),\r\n  IN p_NUMERO varchar(20)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO(\r\n    p_TIPO, p_SERIE, p_NUMERO);\r\n  DELETE FROM fza_movimientos_almacen\r\n   WHERE TIPO_DOC_MOV = p_TIPO\r\n     AND SERIE_DOC_MOV = p_SERIE\r\n     AND NUMERO_DOC_MOV = p_NUMERO;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_ALMACEN_UPDATE`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_MOVIMIENTOS_ALMACEN_UPDATE`(\r\n  IN p_NUMERO_MOV varchar(20),\r\n  IN p_NUEVA_CANTIDAD decimal(19,6),\r\n  IN p_NUEVO_PRECIO decimal(19,6),\r\n  IN p_USUARIO varchar(100)\r\n)\r\nBEGIN\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  INSERT INTO tmp_movimientos_recalculo\r\n    (empresa, almacen, sku, instante_desde)\r\n  SELECT IFNULL(CODIGO_EMP_MOV, \'\'), CODIGO_ALM_MOV, CODIGO_UNIDAD_MOV,\r\n         IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\')\r\n    FROM fza_movimientos_almacen\r\n   WHERE NUMERO_MOV = p_NUMERO_MOV;\r\n  UPDATE fza_movimientos_almacen\r\n     SET CANTIDAD_MOV = p_NUEVA_CANTIDAD,\r\n         PRECIO_COSTE_UNITARIO_MOV = p_NUEVO_PRECIO,\r\n         USUARIO_MODIF = p_USUARIO,\r\n         INSTANTE_MODIF = NOW()\r\n   WHERE NUMERO_MOV = p_NUMERO_MOV;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_CALCULAR_LINEAS`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_INVENTARIOS_CALCULAR_LINEAS`(\r\n  IN p_EMPRESA varchar(10),\r\n  IN p_ALMACEN varchar(10),\r\n  IN p_SERIE varchar(20),\r\n  IN p_NUMERO varchar(20),\r\n  IN p_USUARIO varchar(100),\r\n  IN p_FECHA_DEFECTO datetime\r\n)\r\nBEGIN\r\n  DECLARE v_FIN int DEFAULT 0;\r\n  DECLARE v_LINEA varchar(8);\r\n  DECLARE v_SKU varchar(50);\r\n  DECLARE v_FISICA decimal(19,6);\r\n  DECLARE v_PMP_NUEVO decimal(19,6);\r\n  DECLARE v_ES_CORREGIDO varchar(1);\r\n  DECLARE v_RECUENTO datetime;\r\n  DECLARE v_STOCK decimal(19,6);\r\n  DECLARE v_PMP decimal(19,6);\r\n  DECLARE cur CURSOR FOR\r\n    SELECT LINEA_INVLIN, CODIGO_UNIDAD_INVLIN, CANTIDAD_FISICA_INVLIN,\r\n           PRECIO_MEDIO_NUEVO_INVLIN,\r\n           ESPRECIO_MEDIO_CORREGIDO_INVLIN, FECHA_RECUENTO_INVLIN\r\n      FROM fza_inventarios_lineas\r\n     WHERE CODIGO_EMP_INVLIN = p_EMPRESA\r\n       AND CODIGO_ALM_INVLIN = p_ALMACEN\r\n       AND SERIE_INV_INVLIN = p_SERIE\r\n       AND NUMERO_INV_INVLIN = p_NUMERO;\r\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;\r\n  OPEN cur;\r\n  bucle: LOOP\r\n    FETCH cur INTO v_LINEA, v_SKU, v_FISICA, v_PMP_NUEVO,\r\n                   v_ES_CORREGIDO, v_RECUENTO;\r\n    IF v_FIN = 1 THEN\r\n      LEAVE bucle;\r\n    END IF;\r\n    SET v_RECUENTO = IFNULL(v_RECUENTO, p_FECHA_DEFECTO);\r\n    SELECT IFNULL(SUM(IF(TIPO_MOV = \'E\', CANTIDAD_MOV, -CANTIDAD_MOV)), 0)\r\n      INTO v_STOCK\r\n      FROM fza_movimientos_almacen\r\n     WHERE CODIGO_ALM_MOV = p_ALMACEN\r\n       AND CODIGO_UNIDAD_MOV = v_SKU\r\n       AND IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\') <= v_RECUENTO\r\n       AND ESACTIVO_MOV = \'S\';\r\n    SET v_PMP = IFNULL((\r\n      SELECT PRECIO_MEDIO_MOV\r\n        FROM fza_movimientos_almacen\r\n       WHERE CODIGO_ALM_MOV = p_ALMACEN\r\n         AND CODIGO_UNIDAD_MOV = v_SKU\r\n         AND IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\') <= v_RECUENTO\r\n         AND ESACTIVO_MOV = \'S\'\r\n       ORDER BY IFNULL(FECHA_MOV, \'1000-01-01 00:00:00\') DESC,\r\n                IFNULL(INSTANTE_ALTA, \'1000-01-01 00:00:00\') DESC,\r\n                NUMERO_MOV DESC\r\n       LIMIT 1), 0);\r\n    IF IFNULL(v_ES_CORREGIDO, \'N\') <> \'S\' THEN\r\n      SET v_PMP_NUEVO = v_PMP;\r\n    END IF;\r\n    UPDATE fza_inventarios_lineas\r\n       SET CANTIDAD_TEORICA_INVLIN = v_STOCK,\r\n           PRECIO_MEDIO_INVLIN = v_PMP,\r\n           PRECIO_MEDIO_NUEVO_INVLIN = IFNULL(v_PMP_NUEVO, 0),\r\n           CANTIDAD_DIFERENCIA_INVLIN = v_FISICA - v_STOCK,\r\n           TOTAL_COSTE_DIFERENCIA_INVLIN =\r\n             (v_FISICA * IFNULL(v_PMP_NUEVO, 0)) - (v_STOCK * v_PMP),\r\n           FECHA_RECUENTO_INVLIN = v_RECUENTO,\r\n           USUARIO_MODIF = p_USUARIO,\r\n           INSTANTE_MODIF = NOW()\r\n     WHERE CODIGO_EMP_INVLIN = p_EMPRESA\r\n       AND CODIGO_ALM_INVLIN = p_ALMACEN\r\n       AND SERIE_INV_INVLIN = p_SERIE\r\n       AND NUMERO_INV_INVLIN = p_NUMERO\r\n       AND LINEA_INVLIN = v_LINEA;\r\n  END LOOP;\r\n  CLOSE cur;\r\n  UPDATE fza_inventarios i\r\n     SET TOTAL_UNIDADES_DIFERENCIA_INV = (\r\n           SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)\r\n             FROM fza_inventarios_lineas\r\n            WHERE CODIGO_EMP_INVLIN = p_EMPRESA\r\n              AND CODIGO_ALM_INVLIN = p_ALMACEN\r\n              AND SERIE_INV_INVLIN = p_SERIE\r\n              AND NUMERO_INV_INVLIN = p_NUMERO),\r\n         TOTAL_EUROS_DIFERENCIA_INV = (\r\n           SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)\r\n             FROM fza_inventarios_lineas\r\n            WHERE CODIGO_EMP_INVLIN = p_EMPRESA\r\n              AND CODIGO_ALM_INVLIN = p_ALMACEN\r\n              AND SERIE_INV_INVLIN = p_SERIE\r\n              AND NUMERO_INV_INVLIN = p_NUMERO),\r\n         USUARIO_MODIF = p_USUARIO,\r\n         INSTANTE_MODIF = NOW()\r\n   WHERE CODIGO_EMP_INV = p_EMPRESA\r\n     AND CODIGO_ALM_INV = p_ALMACEN\r\n     AND SERIE_INV = p_SERIE\r\n     AND NUMERO_INV = p_NUMERO;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO`(\r\n  IN p_EMPRESA varchar(10),\r\n  IN p_ALMACEN varchar(10),\r\n  IN p_SERIE varchar(20),\r\n  IN p_NUMERO varchar(20),\r\n  IN p_USUARIO varchar(100)\r\n)\r\nBEGIN\r\n  DECLARE v_ESTADO varchar(20);\r\n  DECLARE v_FECHA datetime;\r\n  DECLARE EXIT HANDLER FOR SQLEXCEPTION\r\n  BEGIN\r\n    ROLLBACK;\r\n    RESIGNAL;\r\n  END;\r\n  START TRANSACTION;\r\n  SELECT ESTADO_INV,\r\n         TIMESTAMP(DATE_SUB(DATE(FECHA_INV), INTERVAL 1 DAY), \'23:59:59\')\r\n    INTO v_ESTADO, v_FECHA\r\n    FROM fza_inventarios\r\n   WHERE CODIGO_EMP_INV = p_EMPRESA\r\n     AND CODIGO_ALM_INV = p_ALMACEN\r\n     AND SERIE_INV = p_SERIE\r\n     AND NUMERO_INV = p_NUMERO\r\n   FOR UPDATE;\r\n  IF IFNULL(v_ESTADO, \'\') <> \'ABIERTO\' THEN\r\n    SIGNAL SQLSTATE \'45000\'\r\n      SET MESSAGE_TEXT = \'El inventario no esta ABIERTO\';\r\n  END IF;\r\n  CALL PRC_FZA_INVENTARIOS_CALCULAR_LINEAS(\r\n    p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);\r\n  COMMIT;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_APLICAR`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_INVENTARIOS_APLICAR`(\r\n  IN p_EMPRESA varchar(10),\r\n  IN p_ALMACEN varchar(10),\r\n  IN p_SERIE varchar(20),\r\n  IN p_NUMERO varchar(20),\r\n  IN p_USUARIO varchar(100)\r\n)\r\nBEGIN\r\n  DECLARE v_FIN int DEFAULT 0;\r\n  DECLARE v_ESTADO varchar(20);\r\n  DECLARE v_FECHA datetime;\r\n  DECLARE v_LINEA varchar(8);\r\n  DECLARE v_ARTICULO varchar(20);\r\n  DECLARE v_SKU varchar(50);\r\n  DECLARE v_TEORICA decimal(19,6);\r\n  DECLARE v_FISICA decimal(19,6);\r\n  DECLARE v_PMP_HIST decimal(19,6);\r\n  DECLARE v_PMP_NUEVO decimal(19,6);\r\n  DECLARE v_RECUENTO datetime;\r\n  DECLARE v_SALIDA datetime;\r\n  DECLARE v_NUM_SALIDA varchar(20);\r\n  DECLARE v_NUM_ENTRADA varchar(20);\r\n  DECLARE cur CURSOR FOR\r\n    SELECT LINEA_INVLIN, CODIGO_ART_INVLIN, CODIGO_UNIDAD_INVLIN,\r\n           CANTIDAD_TEORICA_INVLIN, CANTIDAD_FISICA_INVLIN,\r\n           PRECIO_MEDIO_INVLIN, PRECIO_MEDIO_NUEVO_INVLIN,\r\n           FECHA_RECUENTO_INVLIN\r\n      FROM fza_inventarios_lineas\r\n     WHERE CODIGO_EMP_INVLIN = p_EMPRESA\r\n       AND CODIGO_ALM_INVLIN = p_ALMACEN\r\n       AND SERIE_INV_INVLIN = p_SERIE\r\n       AND NUMERO_INV_INVLIN = p_NUMERO;\r\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;\r\n  DECLARE EXIT HANDLER FOR SQLEXCEPTION\r\n  BEGIN\r\n    ROLLBACK;\r\n    RESIGNAL;\r\n  END;\r\n  START TRANSACTION;\r\n  SELECT ESTADO_INV,\r\n         TIMESTAMP(DATE_SUB(DATE(FECHA_INV), INTERVAL 1 DAY), \'23:59:59\')\r\n    INTO v_ESTADO, v_FECHA\r\n    FROM fza_inventarios\r\n   WHERE CODIGO_EMP_INV = p_EMPRESA\r\n     AND CODIGO_ALM_INV = p_ALMACEN\r\n     AND SERIE_INV = p_SERIE\r\n     AND NUMERO_INV = p_NUMERO\r\n   FOR UPDATE;\r\n  IF IFNULL(v_ESTADO, \'\') <> \'ABIERTO\' THEN\r\n    SIGNAL SQLSTATE \'45000\'\r\n      SET MESSAGE_TEXT = \'El inventario no esta ABIERTO\';\r\n  END IF;\r\n  CALL PRC_FZA_INVENTARIOS_CALCULAR_LINEAS(\r\n    p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  OPEN cur;\r\n  bucle: LOOP\r\n    FETCH cur INTO v_LINEA, v_ARTICULO, v_SKU, v_TEORICA, v_FISICA,\r\n                   v_PMP_HIST, v_PMP_NUEVO, v_RECUENTO;\r\n    IF v_FIN = 1 THEN\r\n      LEAVE bucle;\r\n    END IF;\r\n    SET v_RECUENTO = IFNULL(v_RECUENTO, v_FECHA);\r\n    SET v_SALIDA = DATE_SUB(v_RECUENTO, INTERVAL 1 SECOND);\r\n    SET v_NUM_SALIDA = CONCAT(\'IVS\', LEFT(SHA2(CONCAT_WS(CHAR(31),\r\n      p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, v_LINEA), 256), 17));\r\n    SET v_NUM_ENTRADA = CONCAT(\'IVE\', LEFT(SHA2(CONCAT_WS(CHAR(31),\r\n      p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, v_LINEA), 256), 17));\r\n    CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(\r\n      v_NUM_SALIDA, \'IN\', p_SERIE, p_NUMERO, v_LINEA,\r\n      p_EMPRESA, p_ALMACEN, NULL, v_SKU, \'S\', v_TEORICA,\r\n      v_PMP_HIST, v_TEORICA * v_PMP_HIST, p_USUARIO,\r\n      p_ALMACEN, NULL, NULL, NULL, v_ARTICULO);\r\n    UPDATE fza_movimientos_almacen\r\n       SET FECHA_MOV = v_SALIDA\r\n     WHERE NUMERO_MOV = v_NUM_SALIDA;\r\n    CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(\r\n      v_NUM_ENTRADA, \'IN\', p_SERIE, p_NUMERO, v_LINEA,\r\n      p_EMPRESA, p_ALMACEN, NULL, v_SKU, \'E\', v_FISICA,\r\n      v_PMP_NUEVO, v_FISICA * v_PMP_NUEVO, p_USUARIO,\r\n      p_ALMACEN, NULL, NULL, NULL, v_ARTICULO);\r\n    UPDATE fza_movimientos_almacen\r\n       SET FECHA_MOV = v_RECUENTO\r\n     WHERE NUMERO_MOV = v_NUM_ENTRADA;\r\n    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR(\r\n      p_EMPRESA, p_ALMACEN, v_SKU, v_SALIDA);\r\n  END LOOP;\r\n  CLOSE cur;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\n  UPDATE fza_inventarios\r\n     SET ESTADO_INV = \'APLICADO\',\r\n         TOTAL_UNIDADES_DIFERENCIA_INV = (\r\n           SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)\r\n             FROM fza_inventarios_lineas\r\n            WHERE CODIGO_EMP_INVLIN = p_EMPRESA\r\n              AND CODIGO_ALM_INVLIN = p_ALMACEN\r\n              AND SERIE_INV_INVLIN = p_SERIE\r\n              AND NUMERO_INV_INVLIN = p_NUMERO),\r\n         TOTAL_EUROS_DIFERENCIA_INV = (\r\n           SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)\r\n             FROM fza_inventarios_lineas\r\n            WHERE CODIGO_EMP_INVLIN = p_EMPRESA\r\n              AND CODIGO_ALM_INVLIN = p_ALMACEN\r\n              AND SERIE_INV_INVLIN = p_SERIE\r\n              AND NUMERO_INV_INVLIN = p_NUMERO),\r\n         USUARIO_MODIF = p_USUARIO,\r\n         INSTANTE_MODIF = NOW()\r\n   WHERE CODIGO_EMP_INV = p_EMPRESA\r\n     AND CODIGO_ALM_INV = p_ALMACEN\r\n     AND SERIE_INV = p_SERIE\r\n     AND NUMERO_INV = p_NUMERO;\r\n  COMMIT;\r\nEND;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL`(\r\n  IN p_EMPRESA varchar(10),\r\n  IN p_ALMACEN varchar(10),\r\n  IN p_SERIE varchar(20),\r\n  IN p_NUMERO varchar(20),\r\n  IN p_USUARIO varchar(100)\r\n)\r\nBEGIN\r\n  DECLARE v_ESTADO varchar(20);\r\n  DECLARE EXIT HANDLER FOR SQLEXCEPTION\r\n  BEGIN\r\n    ROLLBACK;\r\n    RESIGNAL;\r\n  END;\r\n  START TRANSACTION;\r\n  SELECT ESTADO_INV INTO v_ESTADO\r\n    FROM fza_inventarios\r\n   WHERE CODIGO_EMP_INV = p_EMPRESA\r\n     AND CODIGO_ALM_INV = p_ALMACEN\r\n     AND SERIE_INV = p_SERIE\r\n     AND NUMERO_INV = p_NUMERO\r\n   FOR UPDATE;\r\n  IF IFNULL(v_ESTADO, \'\') <> \'APLICADO\' THEN\r\n    SIGNAL SQLSTATE \'45000\'\r\n      SET MESSAGE_TEXT = \'El inventario no esta APLICADO\';\r\n  END IF;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO(\r\n    \'IN\', p_SERIE, p_NUMERO);\r\n  DELETE FROM fza_movimientos_almacen\r\n   WHERE TIPO_DOC_MOV = \'IN\'\r\n     AND SERIE_DOC_MOV = p_SERIE\r\n     AND NUMERO_DOC_MOV = p_NUMERO;\r\n  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();\r\n  UPDATE fza_inventarios\r\n     SET ESTADO_INV = \'ABIERTO\',\r\n         USUARIO_MODIF = p_USUARIO,\r\n         INSTANTE_MODIF = NOW()\r\n   WHERE CODIGO_EMP_INV = p_EMPRESA\r\n     AND CODIGO_ALM_INV = p_ALMACEN\r\n     AND SERIE_INV = p_SERIE\r\n     AND NUMERO_INV = p_NUMERO;\r\n  COMMIT;\r\nEND;;\r\nDELIMITER ;\r\n','2026-08-07 11:34:04','2026-08-07 11:34:04','Administrador','Administrador'),
('618',NULL,'-- SPDX-License-Identifier: MPL-2.0\r\n-- Conserva el orden de las tallas de cada articulo procedente de\r\n-- dbo.ocarttal.Orden. Es idempotente y no altera las asignaciones existentes.\r\n\r\nALTER TABLE `fza_articulos_atributos_basicos`\r\n  ADD COLUMN IF NOT EXISTS `ORDEN_AAB` int(11) NULL DEFAULT NULL\r\n    COMMENT \'Orden del valor dentro del articulo; en tallas procede de ocarttal.Orden.\'\r\n    AFTER `DESCRIPCION_AAB`;\r\n\r\n-- Fallback razonable hasta volver a ejecutar la migracion articulos_tallas.\r\n-- Esa migracion sustituye este valor global por el Orden exacto de ocarttal.\r\nUPDATE `fza_articulos_atributos_basicos` aab\r\nJOIN `fza_atributos_valores` av ON av.ID_AV = aab.ID_AV_AAB\r\n   SET aab.ORDEN_AAB = av.ORDEN_AV\r\n WHERE av.ID_VA_AV = \'TAL\'\r\n   AND aab.ORDEN_AAB IS NULL;\r\n','2026-08-07 16:05:08','2026-08-07 16:05:08','Administrador','Administrador'),
('619','ses_copiar_descripcion_familia','-- Añade la opción que decide qué descripción recibe un artículo nuevo\r\n-- materializado desde una sesión de compra.\r\n-- S: usa DESCRIPCION_FAM y conserva DESCRIPCION_SESLIN si la familia no\r\n--    tiene descripción.\r\n-- N: conserva siempre la descripción importada en DESCRIPCION_SESLIN.\r\n\r\nSET @existe := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_compras_sesiones\'\r\n     AND COLUMN_NAME = \'ESCOPIAR_DESCRIPCION_FAM_SES\'\r\n);\r\nSET @sql := IF(\r\n  @existe = 0,\r\n  \'ALTER TABLE `fza_compras_sesiones`\r\n     ADD COLUMN `ESCOPIAR_DESCRIPCION_FAM_SES` varchar(1) NOT NULL DEFAULT \'\'S\'\'\r\n     AFTER `ESFORMATO_DISTRIBUIDO_SES`\',\r\n  \'SELECT 1\'\r\n);\r\nPREPARE sentencia FROM @sql;\r\nEXECUTE sentencia;\r\nDEALLOCATE PREPARE sentencia;\r\n','2026-08-08 20:04:43','2026-08-08 20:04:43','Administrador','Administrador'),
('620','caja_stock_pivotado_orden_tallas','-- SPDX-License-Identifier: MPL-2.0\r\n-- Punto de partida:\r\n--   C:\\DISCO_DURO\\proyectos\\factuzam_web\\factuzam_original.sql\r\n--\r\n-- Corrige el orden de las columnas dinamicas de talla en el stock rapido de\r\n-- TPV/Operacion de Caja y en la pestana Stock del mantenimiento de Articulos.\r\n--\r\n-- Prioridad del orden:\r\n--   1. ORDEN_AAB: orden especifico del valor para el articulo.\r\n--   2. ORDEN_ACD: orden del valor en la coleccion asignada al articulo.\r\n--   3. ORDEN_AV:  orden global del valor.\r\n--\r\n-- Solo se crean columnas para valores presentes en los SKU del articulo, igual\r\n-- que antes. El script es idempotente: asegura ORDEN_AAB para bases anteriores\r\n-- al modelo original actual y recrea los dos procedimientos que consumen las\r\n-- dos pantallas afectadas. No rellena ni modifica los valores de ORDEN_AAB.\r\n\r\nALTER TABLE `fza_articulos_atributos_basicos`\r\n  ADD COLUMN IF NOT EXISTS `ORDEN_AAB` int(11) NULL DEFAULT NULL\r\n    COMMENT \'Orden del valor dentro del articulo; en tallas procede de ocarttal.Orden.\'\r\n    AFTER `DESCRIPCION_AAB`;\r\n\r\n-- La consulta rapida de Caja genera las tallas como columnas dinamicas.\r\n-- Se recrean las dos variantes porque el perfil SQL puede elegir la que\r\n-- incluye almacenes sin stock (WITHZ).\r\nDROP PROCEDURE IF EXISTS `PRC_GET_CAJA_STOCK_PIVOTADO`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_GET_CAJA_STOCK_PIVOTADO`(IN p_input VARCHAR(50))\r\nBEGIN\r\n    DECLARE v_codigo_articulo VARCHAR(20);\r\n    DECLARE v_es_sku BOOLEAN DEFAULT FALSE;\r\n    DECLARE v_id_atributo_pivot VARCHAR(20);\r\n    DECLARE v_id_atributo_grupo VARCHAR(20);\r\n    DECLARE v_valor_grupo_filtro VARCHAR(50) DEFAULT NULL;\r\n    DECLARE v_columnas_dinamicas TEXT;\r\n    SELECT COALESCE(\r\n        (SELECT CODIGO_ART_ART\r\n           FROM fza_articulos\r\n          WHERE CODIGO_ART_ART = p_input\r\n          LIMIT 1),\r\n        (SELECT CODIGO_ART_SKU\r\n           FROM fza_articulos_skus\r\n          WHERE CODIGO_UNIDAD_SKU = p_input\r\n          LIMIT 1)\r\n    ) INTO v_codigo_articulo;\r\n    IF v_codigo_articulo IS NOT NULL AND v_codigo_articulo <> p_input THEN\r\n        SET v_es_sku = TRUE;\r\n    END IF;\r\n    IF v_codigo_articulo IS NOT NULL THEN\r\n        SELECT vat.ID_ATB_VA\r\n          INTO v_id_atributo_pivot\r\n          FROM fza_articulos art\r\n          JOIN fza_variaciones_atributos vat\r\n            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART\r\n         WHERE art.CODIGO_ART_ART = v_codigo_articulo\r\n         ORDER BY vat.ORDEN_VA DESC\r\n         LIMIT 1;\r\n        SELECT vat.ID_ATB_VA\r\n          INTO v_id_atributo_grupo\r\n          FROM fza_articulos art\r\n          JOIN fza_variaciones_atributos vat\r\n            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART\r\n         WHERE art.CODIGO_ART_ART = v_codigo_articulo\r\n           AND vat.ID_ATB_VA <> COALESCE(v_id_atributo_pivot, \'\')\r\n         ORDER BY vat.ORDEN_VA DESC\r\n         LIMIT 1;\r\n    END IF;\r\n    IF v_id_atributo_pivot IS NOT NULL THEN\r\n        IF v_es_sku = TRUE AND v_id_atributo_grupo IS NOT NULL THEN\r\n            SET v_valor_grupo_filtro = (\r\n                SELECT av.AV\r\n                  FROM fza_atributos_sku ask\r\n                  JOIN fza_atributos_valores av\r\n                    ON ask.ID_AV_SA = av.ID_AV\r\n                 WHERE ask.CODIGO_UNIDAD_SKU_SA = p_input\r\n                   AND av.ID_VA_AV = v_id_atributo_grupo\r\n                 LIMIT 1\r\n            );\r\n        END IF;\r\n        SELECT GROUP_CONCAT(DISTINCT\r\n            CONCAT(\r\n                \'SUM(CASE WHEN av_p.AV = \'\'\',\r\n                REPLACE(t.AV, \'\'\'\', \'\'\'\'\'\'),\r\n                \'\'\' THEN stk.CANTIDAD_STK ELSE 0 END) AS `\',\r\n                REPLACE(t.AV, \'`\', \'``\'), \'`\'\r\n            )\r\n            ORDER BY t.ORDEN_TALLA, t.ID_AV\r\n        ) INTO v_columnas_dinamicas\r\n        FROM (\r\n            SELECT av.AV,\r\n                   MIN(av.ID_AV) AS ID_AV,\r\n                   COALESCE(MIN(aab.ORDEN_AAB),\r\n                            MIN(acd.ORDEN_ACD),\r\n                            MIN(av.ORDEN_AV)) AS ORDEN_TALLA\r\n              FROM fza_articulos_skus sk\r\n              JOIN fza_atributos_sku ask\r\n                ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA\r\n              JOIN fza_atributos_valores av\r\n                ON ask.ID_AV_SA = av.ID_AV\r\n              LEFT JOIN fza_articulos_atributos_basicos aab\r\n                ON aab.CODIGO_ART_AAB = sk.CODIGO_ART_SKU\r\n               AND aab.ID_AV_AAB = av.ID_AV\r\n              LEFT JOIN fza_articulos_conjuntos_asign aca\r\n                ON aca.CODIGO_ART_ACA = sk.CODIGO_ART_SKU\r\n               AND aca.ID_VA_ACA = av.ID_VA_AV\r\n              LEFT JOIN fza_atributos_conjuntos_det acd\r\n                ON acd.ID_AC_ACD = aca.ID_AC_ACA\r\n               AND acd.ID_AV_ACD = av.ID_AV\r\n             WHERE sk.CODIGO_ART_SKU = v_codigo_articulo\r\n               AND av.ID_VA_AV = v_id_atributo_pivot\r\n             GROUP BY av.AV\r\n        ) t;\r\n        IF v_columnas_dinamicas IS NOT NULL THEN\r\n            SET @sql = CONCAT(\r\n                \'SELECT\r\n                    CONCAT(\'\'\', v_codigo_articulo, \'\'\',\r\n                        CASE\r\n                            WHEN av_g.AV IS NOT NULL THEN CONCAT(\'\'/\'\', av_g.AV)\r\n                            ELSE \'\'\'\'\r\n                        END\r\n                    ) AS Codigo,\r\n                    alm.NOMBRE_ALM_ALM AS Almacen, \',\r\n                    v_columnas_dinamicas, \',\r\n                    SUM(stk.CANTIDAD_STK) AS Total\r\n                 FROM fza_articulos_stockactual stk\r\n                 JOIN fza_almacenes alm\r\n                   ON stk.CODIGO_ALM_STK = alm.CODIGO_ALM_ALM\r\n                 JOIN fza_articulos_skus sk\r\n                   ON stk.CODIGO_UNIDAD_STK = sk.CODIGO_UNIDAD_SKU\r\n                 JOIN fza_atributos_sku ask_p\r\n                   ON sk.CODIGO_UNIDAD_SKU = ask_p.CODIGO_UNIDAD_SKU_SA\r\n                 JOIN fza_atributos_valores av_p\r\n                   ON ask_p.ID_AV_SA = av_p.ID_AV\r\n                  AND av_p.ID_VA_AV = \'\'\', v_id_atributo_pivot, \'\'\'\r\n                 LEFT JOIN fza_atributos_sku ask_g\r\n                   ON sk.CODIGO_UNIDAD_SKU = ask_g.CODIGO_UNIDAD_SKU_SA\r\n                 LEFT JOIN fza_atributos_valores av_g\r\n                   ON ask_g.ID_AV_SA = av_g.ID_AV\r\n                  AND av_g.ID_VA_AV = \'\'\',\r\n                    IFNULL(v_id_atributo_grupo, \'xxx\'), \'\'\'\r\n                 WHERE sk.CODIGO_ART_SKU = \'\'\', v_codigo_articulo, \'\'\' \',\r\n                 CASE WHEN v_valor_grupo_filtro IS NOT NULL THEN\r\n                    CONCAT(\' AND av_g.AV = \'\'\',\r\n                           REPLACE(v_valor_grupo_filtro, \'\'\'\', \'\'\'\'\'\'), \'\'\' \')\r\n                 ELSE \'\' END, \'\r\n                 GROUP BY av_g.AV, alm.NOMBRE_ALM_ALM\r\n                 ORDER BY alm.NOMBRE_ALM_ALM, av_g.AV\'\r\n            );\r\n            PREPARE stmt FROM @sql;\r\n            EXECUTE stmt;\r\n            DEALLOCATE PREPARE stmt;\r\n        END IF;\r\n    END IF;\r\n    IF v_columnas_dinamicas IS NULL THEN\r\n        SELECT stk.CODIGO_UNIDAD_STK AS Codigo,\r\n               alm.NOMBRE_ALM_ALM AS Almacen,\r\n               SUM(stk.CANTIDAD_STK) AS Stock_Total\r\n          FROM fza_articulos_stockactual stk\r\n          JOIN fza_almacenes alm\r\n            ON stk.CODIGO_ALM_STK = alm.CODIGO_ALM_ALM\r\n         WHERE stk.CODIGO_UNIDAD_STK = p_input\r\n         GROUP BY stk.CODIGO_UNIDAD_STK, alm.NOMBRE_ALM_ALM\r\n         ORDER BY alm.NOMBRE_ALM_ALM;\r\n    END IF;\r\nEND ;;\r\nDELIMITER ;\r\n\r\nDROP PROCEDURE IF EXISTS `PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ`;\r\nDELIMITER ;;\r\nCREATE PROCEDURE `PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ`(IN p_input VARCHAR(50))\r\nBEGIN\r\n    DECLARE v_codigo_articulo VARCHAR(20);\r\n    DECLARE v_es_sku BOOLEAN DEFAULT FALSE;\r\n    DECLARE v_id_atributo_pivot VARCHAR(20);\r\n    DECLARE v_nombre_atributo_pivot VARCHAR(50);\r\n    DECLARE v_columnas_dinamicas TEXT;\r\n    DECLARE v_id_atributo_fila VARCHAR(20) DEFAULT NULL;\r\n    DECLARE v_nombre_atributo_fila VARCHAR(50) DEFAULT NULL;\r\n    DECLARE v_select_fila TEXT DEFAULT \'\';\r\n    DECLARE v_join_fila TEXT DEFAULT \'\';\r\n    DECLARE v_groupby_fila TEXT DEFAULT \'\';\r\n    DECLARE v_src_select_fila TEXT DEFAULT \'\';\r\n    DECLARE v_filtros_fijos TEXT DEFAULT \'\';\r\n    DECLARE v_sql_query TEXT;\r\n    SELECT COALESCE(\r\n        (SELECT CODIGO_ART_ART\r\n           FROM fza_articulos\r\n          WHERE CODIGO_ART_ART = p_input\r\n          LIMIT 1),\r\n        (SELECT CODIGO_ART_SKU\r\n           FROM fza_articulos_skus\r\n          WHERE CODIGO_UNIDAD_SKU = p_input\r\n          LIMIT 1)\r\n    ) INTO v_codigo_articulo;\r\n    IF v_codigo_articulo IS NOT NULL AND v_codigo_articulo <> p_input THEN\r\n        SET v_es_sku = TRUE;\r\n    END IF;\r\n    IF v_codigo_articulo IS NOT NULL THEN\r\n        SELECT vat.ID_ATB_VA, vat.NOMBRE_VA\r\n          INTO v_id_atributo_pivot, v_nombre_atributo_pivot\r\n          FROM fza_articulos art\r\n          JOIN fza_variaciones_atributos vat\r\n            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART\r\n         WHERE art.CODIGO_ART_ART = v_codigo_articulo\r\n         ORDER BY vat.ORDEN_VA DESC\r\n         LIMIT 1;\r\n    END IF;\r\n    IF v_codigo_articulo IS NOT NULL AND v_es_sku = FALSE THEN\r\n        SELECT vat.ID_ATB_VA, vat.NOMBRE_VA\r\n          INTO v_id_atributo_fila, v_nombre_atributo_fila\r\n          FROM fza_articulos art\r\n          JOIN fza_variaciones_atributos vat\r\n            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART\r\n         WHERE art.CODIGO_ART_ART = v_codigo_articulo\r\n           AND vat.ID_ATB_VA <> v_id_atributo_pivot\r\n         ORDER BY vat.ORDEN_VA ASC\r\n         LIMIT 1;\r\n    END IF;\r\n    IF v_id_atributo_pivot IS NOT NULL THEN\r\n        IF v_id_atributo_fila IS NOT NULL THEN\r\n            SET v_select_fila = CONCAT(\r\n                \', COALESCE(src.VALOR_FILA, \'\'-\'\') AS `\',\r\n                v_nombre_atributo_fila, \'`\');\r\n            SET v_src_select_fila = \', av_fila.AV AS VALOR_FILA\';\r\n            SET v_join_fila = CONCAT(\r\n                \' LEFT JOIN fza_atributos_sku ask_fila\',\r\n                \' ON sk.CODIGO_UNIDAD_SKU = ask_fila.CODIGO_UNIDAD_SKU_SA\',\r\n                \' LEFT JOIN fza_atributos_valores av_fila\',\r\n                \' ON ask_fila.ID_AV_SA = av_fila.ID_AV\',\r\n                \' AND av_fila.ID_VA_AV = \'\'\', v_id_atributo_fila, \'\'\' \');\r\n            SET v_groupby_fila = \', src.VALOR_FILA\';\r\n        END IF;\r\n        SELECT GROUP_CONCAT(DISTINCT\r\n            CONCAT(\r\n                \'SUM(CASE WHEN src.AV = \'\'\', t.AV,\r\n                \'\'\' THEN src.CANTIDAD_STK ELSE 0 END) AS `\', t.AV, \'`\'\r\n            )\r\n            ORDER BY t.ORDEN_TALLA, t.ID_AV\r\n        ) INTO v_columnas_dinamicas\r\n        FROM (\r\n            SELECT av.AV,\r\n                   MIN(av.ID_AV) AS ID_AV,\r\n                   COALESCE(MIN(aab.ORDEN_AAB),\r\n                            MIN(acd.ORDEN_ACD),\r\n                            MIN(av.ORDEN_AV)) AS ORDEN_TALLA\r\n              FROM fza_articulos_skus sk\r\n              JOIN fza_atributos_sku ask\r\n                ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA\r\n              JOIN fza_atributos_valores av\r\n                ON ask.ID_AV_SA = av.ID_AV\r\n              LEFT JOIN fza_articulos_atributos_basicos aab\r\n                ON aab.CODIGO_ART_AAB = sk.CODIGO_ART_SKU\r\n               AND aab.ID_AV_AAB = av.ID_AV\r\n              LEFT JOIN fza_articulos_conjuntos_asign aca\r\n                ON aca.CODIGO_ART_ACA = sk.CODIGO_ART_SKU\r\n               AND aca.ID_VA_ACA = av.ID_VA_AV\r\n              LEFT JOIN fza_atributos_conjuntos_det acd\r\n                ON acd.ID_AC_ACD = aca.ID_AC_ACA\r\n               AND acd.ID_AV_ACD = av.ID_AV\r\n             WHERE sk.CODIGO_ART_SKU = v_codigo_articulo\r\n               AND av.ID_VA_AV = v_id_atributo_pivot\r\n             GROUP BY av.AV\r\n        ) t;\r\n        IF v_es_sku = TRUE THEN\r\n            SELECT GROUP_CONCAT(\r\n                CONCAT(\r\n                    \' AND EXISTS (SELECT 1 FROM fza_atributos_sku f_ask \',\r\n                    \' JOIN fza_atributos_valores f_av\',\r\n                    \' ON f_ask.ID_AV_SA = f_av.ID_AV \',\r\n                    \' WHERE f_ask.CODIGO_UNIDAD_SKU_SA = sk.CODIGO_UNIDAD_SKU \',\r\n                    \' AND f_av.ID_VA_AV = \'\'\', av.ID_VA_AV, \'\'\' \',\r\n                    \' AND f_av.AV = \'\'\', av.AV, \'\'\') \'\r\n                ) SEPARATOR \' \'\r\n            ) INTO v_filtros_fijos\r\n              FROM fza_atributos_sku ask\r\n              JOIN fza_atributos_valores av\r\n                ON ask.ID_AV_SA = av.ID_AV\r\n             WHERE ask.CODIGO_UNIDAD_SKU_SA = p_input\r\n               AND av.ID_VA_AV <> v_id_atributo_pivot;\r\n        END IF;\r\n        IF v_filtros_fijos IS NULL THEN\r\n            SET v_filtros_fijos = \'\';\r\n        END IF;\r\n        IF v_columnas_dinamicas IS NOT NULL THEN\r\n            SET @sql = CONCAT(\r\n                \'SELECT\r\n                    alm.NOMBRE_ALM_ALM AS Almacen\',\r\n                    v_select_fila, \', \',\r\n                    v_columnas_dinamicas, \',\r\n                    COALESCE(SUM(src.CANTIDAD_STK), 0) AS Total\r\n                 FROM fza_almacenes alm\r\n                 LEFT JOIN (\r\n                    SELECT stk.CODIGO_ALM_STK, av.AV, stk.CANTIDAD_STK\',\r\n                    v_src_select_fila, \'\r\n                    FROM fza_articulos_stockactual stk\r\n                    JOIN fza_articulos_skus sk\r\n                      ON stk.CODIGO_UNIDAD_STK = sk.CODIGO_UNIDAD_SKU\r\n                    JOIN fza_atributos_sku ask\r\n                      ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA\r\n                    JOIN fza_atributos_valores av\r\n                      ON ask.ID_AV_SA = av.ID_AV\',\r\n                    v_join_fila, \'\r\n                    WHERE sk.CODIGO_ART_SKU = \'\'\', v_codigo_articulo, \'\'\'\r\n                      AND av.ID_VA_AV = \'\'\', v_id_atributo_pivot, \'\'\' \',\r\n                      v_filtros_fijos, \'\r\n                 ) src ON alm.CODIGO_ALM_ALM = src.CODIGO_ALM_STK\r\n                 WHERE alm.ESACTIVO_ALM = \'\'S\'\'\r\n                 GROUP BY alm.NOMBRE_ALM_ALM\', v_groupby_fila, \'\r\n                 ORDER BY alm.NOMBRE_ALM_ALM\', v_groupby_fila\r\n            );\r\n            PREPARE stmt FROM @sql;\r\n            EXECUTE stmt;\r\n            DEALLOCATE PREPARE stmt;\r\n        END IF;\r\n    END IF;\r\n    IF v_id_atributo_pivot IS NULL OR v_columnas_dinamicas IS NULL THEN\r\n        SELECT alm.NOMBRE_ALM_ALM AS Almacen,\r\n               COALESCE(SUM(stk.CANTIDAD_STK), 0) AS `Stock Total`\r\n          FROM fza_almacenes alm\r\n          LEFT JOIN fza_articulos_stockactual stk\r\n            ON alm.CODIGO_ALM_ALM = stk.CODIGO_ALM_STK\r\n           AND stk.CODIGO_UNIDAD_STK = p_input\r\n         WHERE alm.ESACTIVO_ALM = \'S\'\r\n         GROUP BY alm.NOMBRE_ALM_ALM\r\n         ORDER BY alm.NOMBRE_ALM_ALM;\r\n    END IF;\r\nEND ;;\r\nDELIMITER ;\r\n\r\n-- Verificacion manual sugerida:\r\n-- CALL PRC_GET_CAJA_STOCK_PIVOTADO(\'BOTIN-ANIT\');\r\n-- CALL PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ(\'BOTIN-ANIT\');\r\n-- En ambos resultados las columnas existentes deben quedar 37,38,39,40,41.\r\n','2026-08-10 16:56:27','2026-08-10 16:56:27','Administrador','Administrador'),
('621','traspasos_solicitudes_fecha_hora','-- =============================================================================\r\n-- Solicitudes de traspaso: conservar fecha y hora de la solicitud\r\n-- =============================================================================\r\n-- FECHA_TRSOL se creo originalmente como date. Se convierte a datetime para\r\n-- que las nuevas solicitudes puedan guardar el instante mediante\r\n-- CURRENT_TIMESTAMP, sin recurrir al campo de auditoria INSTANTE_ALTA.\r\n--\r\n-- Las solicitudes existentes conservan su fecha y quedan a las 00:00:00,\r\n-- porque el tipo anterior no guardaba la hora.\r\n-- =============================================================================\r\n\r\nSET @sExisteTabla := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n);\r\n\r\nSET @sTipoFecha := (\r\n  SELECT LOWER(DATA_TYPE)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND COLUMN_NAME  = \'FECHA_TRSOL\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteTabla > 0 AND @sTipoFecha = \'date\',\r\n  \'ALTER TABLE fza_traspasos_solicitudes\r\n     MODIFY COLUMN FECHA_TRSOL datetime NULL DEFAULT CURRENT_TIMESTAMP\',\r\n  \'SELECT \'\'FECHA_TRSOL ya es datetime o no existe la tabla\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteConfigCampos := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_config_campos\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteConfigCampos > 0,\r\n  \'UPDATE fza_config_campos\r\n      SET TITULO_VISUAL_CC = \'\'Fecha / hora\'\',\r\n          ANCHO_COLUMNA_CC = 165\r\n    WHERE TABLA_OBJETIVO_CC = \'\'fza_traspasos_solicitudes\'\'\r\n      AND OBJETIVO_CC = \'\'FECHA_TRSOL\'\'\r\n      AND (TITULO_VISUAL_CC <> \'\'Fecha / hora\'\'\r\n           OR ANCHO_COLUMNA_CC <> 165)\',\r\n  \'SELECT \'\'No existe fza_config_campos\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteTraducciones := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traducciones\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteTraducciones > 0,\r\n  \'UPDATE fza_traducciones\r\n      SET TEXTO_TRAD = CASE IDIOMA_TRAD\r\n            WHEN \'\'es-ES\'\' THEN \'\'Fecha / hora\'\'\r\n            WHEN \'\'en-GB\'\' THEN \'\'Date / time\'\'\r\n            WHEN \'\'ca-ES\'\' THEN \'\'Data / hora\'\'\r\n          END,\r\n          INSTANTE_MODIF = CURRENT_TIMESTAMP,\r\n          USUARIO_MODIF = \'\'SISTEMA\'\'\r\n    WHERE CLAVE_TRAD = \'\'inLibMsgCaja.SCaptionColFechaSolicitud\'\'\r\n      AND IDIOMA_TRAD IN (\'\'es-ES\'\', \'\'en-GB\'\', \'\'ca-ES\'\')\r\n      AND TEXTO_TRAD <> CASE IDIOMA_TRAD\r\n            WHEN \'\'es-ES\'\' THEN \'\'Fecha / hora\'\'\r\n            WHEN \'\'en-GB\'\' THEN \'\'Date / time\'\'\r\n            WHEN \'\'ca-ES\'\' THEN \'\'Data / hora\'\'\r\n          END\',\r\n  \'SELECT \'\'No existe fza_traducciones\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n','2026-08-11 05:18:00','2026-08-11 05:18:00','Administrador','Administrador'),
('622','traspasos_caja','-- ============================================================================\r\n-- Traspasos en caja — solicitudes de traspaso entre almacenes\r\n-- Diseno DDL siguiendo LIBRO_DE_ESTILO_BBDD.md\r\n-- (detalle funcional en DESARROLLOS EN CURSO/traspasos_caja.md).\r\n--\r\n-- Crea las dos tablas del CICLO DE SOLICITUDES (peticion -> atencion):\r\n--   fza_traspasos_solicitudes         (cabecera, sufijo TRSOL)\r\n--   fza_traspasos_solicitudes_lineas  (lineas,   sufijo TRSOLLIN)\r\n-- y siembra el contador global \'TS\' para numerar las solicitudes.\r\n--\r\n-- El TRASPASO EJECUTADO no necesita tablas nuevas: se graba en\r\n-- fza_caja_operaciones (TIPO_OPERACION_OPCAJA TR/TA) + fza_movimientos_almacen\r\n-- (par S+E). Estas tablas solo guardan la PETICION pendiente y su estado.\r\n--\r\n-- Idempotente: pasa por INFORMATION_SCHEMA (TABLES / STATISTICS) antes de crear\r\n-- cada tabla e indice; el contador se siembra solo si no existe la fila global.\r\n-- Sufijos TRSOL / TRSOLLIN dados de alta en LIBRO_DE_ESTILO_BBDD.md (§2) y en\r\n-- src/utilnormbbdd/UNormalizerEngine.pas (InitDefaults).\r\n-- ============================================================================\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 1. Cabecera de la solicitud (TRSOL)\r\n-- ---------------------------------------------------------------------------\r\nSET @tab_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n);\r\nSET @ddl := IF(@tab_exists = 0,\r\n  \'CREATE TABLE `fza_traspasos_solicitudes` (\'\r\n  \'  `NUMERO_TRSOL`             varchar(20)   NOT NULL,\'\r\n  \'  `SERIE_TRSOL`              varchar(20)   NOT NULL,\'\r\n  \'  `FECHA_TRSOL`              datetime      NULL DEFAULT CURRENT_TIMESTAMP,\'\r\n  \'  `ESTADO_TRSOL`             varchar(20)   NOT NULL DEFAULT \'\'PENDIENTE\'\'\'\r\n  \'       COMMENT \'\'PENDIENTE, PARCIAL, ATENDIDA, RECHAZADA, CANCELADA\'\',\'\r\n  \'  `CODIGO_EMP_TRSOL`         varchar(20)   NOT NULL,\'\r\n  \'  `CODIGO_ALM_ORIGEN_TRSOL`  varchar(10)   NOT NULL\'\r\n  \'       COMMENT \'\'A quien se pide = origen del futuro traspaso\'\',\'\r\n  \'  `CODIGO_ALM_DESTINO_TRSOL` varchar(10)   NOT NULL\'\r\n  \'       COMMENT \'\'Quien pide = propio = destino del futuro traspaso\'\',\'\r\n  \'  `CODIGO_EMP_CONTRA_TRSOL`  varchar(20)   NULL DEFAULT NULL,\'\r\n  \'  `CODIGO_CAJA_TRSOL`        varchar(10)   NULL DEFAULT NULL,\'\r\n  \'  `CODIGO_EMPLEADO_TRSOL`    varchar(20)   NULL DEFAULT NULL,\'\r\n  \'  `OBSERVACIONES_TRSOL`      varchar(1000) NULL DEFAULT \'\'\'\',\'\r\n  \'  `INSTANTE_MODIF`           timestamp     NOT NULL\'\r\n  \'       DEFAULT current_timestamp() ON UPDATE current_timestamp(),\'\r\n  \'  `INSTANTE_ALTA`            timestamp     NOT NULL\'\r\n  \'       DEFAULT \'\'0000-00-00 00:00:00\'\',\'\r\n  \'  `USUARIO_ALTA`             varchar(100)  NOT NULL,\'\r\n  \'  `USUARIO_MODIF`            varchar(100)  NOT NULL,\'\r\n  \'  PRIMARY KEY (`NUMERO_TRSOL`,`SERIE_TRSOL`)\'\r\n  \') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @idx_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND INDEX_NAME   = \'IDX_TRSOL_ESTADO\'\r\n);\r\nSET @ddl := IF(@idx_exists = 0,\r\n  \'ALTER TABLE `fza_traspasos_solicitudes` \'\r\n  \'ADD INDEX `IDX_TRSOL_ESTADO` (`ESTADO_TRSOL`)\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @idx_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND INDEX_NAME   = \'IDX_TRSOL_ORIGEN\'\r\n);\r\nSET @ddl := IF(@idx_exists = 0,\r\n  \'ALTER TABLE `fza_traspasos_solicitudes` \'\r\n  \'ADD INDEX `IDX_TRSOL_ORIGEN` (`CODIGO_ALM_ORIGEN_TRSOL`,`ESTADO_TRSOL`)\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @idx_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND INDEX_NAME   = \'IDX_TRSOL_DESTINO\'\r\n);\r\nSET @ddl := IF(@idx_exists = 0,\r\n  \'ALTER TABLE `fza_traspasos_solicitudes` \'\r\n  \'ADD INDEX `IDX_TRSOL_DESTINO` (`CODIGO_ALM_DESTINO_TRSOL`,`ESTADO_TRSOL`)\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @idx_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND INDEX_NAME   = \'IDX_TRSOL_EMP\'\r\n);\r\nSET @ddl := IF(@idx_exists = 0,\r\n  \'ALTER TABLE `fza_traspasos_solicitudes` \'\r\n  \'ADD INDEX `IDX_TRSOL_EMP` (`CODIGO_EMP_TRSOL`)\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 2. Lineas de la solicitud (TRSOLLIN)\r\n-- ---------------------------------------------------------------------------\r\nSET @tab_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes_lineas\'\r\n);\r\nSET @ddl := IF(@tab_exists = 0,\r\n  \'CREATE TABLE `fza_traspasos_solicitudes_lineas` (\'\r\n  \'  `NUMERO_TRSOL_TRSOLLIN`         varchar(20)   NOT NULL,\'\r\n  \'  `SERIE_TRSOL_TRSOLLIN`          varchar(20)   NOT NULL,\'\r\n  \'  `LINEA_TRSOLLIN`                varchar(4)    NOT NULL,\'\r\n  \'  `CODIGO_ART_TRSOLLIN`           varchar(20)   NULL DEFAULT NULL,\'\r\n  \'  `CODIGO_UNIDAD_TRSOLLIN`        varchar(50)   NOT NULL\'\r\n  \'       COMMENT \'\'SKU solicitado\'\',\'\r\n  \'  `DESCRIPCION_ARTICULO_TRSOLLIN` varchar(100)  NULL DEFAULT NULL,\'\r\n  \'  `CANTIDAD_PEDIDA_TRSOLLIN`      decimal(19,6) NOT NULL DEFAULT \'\'0.000000\'\',\'\r\n  \'  `CANTIDAD_SERVIDA_TRSOLLIN`     decimal(19,6) NOT NULL DEFAULT \'\'0.000000\'\'\'\r\n  \'       COMMENT \'\'Unidades ya atendidas (para estado PARCIAL)\'\',\'\r\n  \'  `ESATENDIDA_TRSOLLIN`           varchar(1)    NOT NULL DEFAULT \'\'N\'\',\'\r\n  \'  `MOTIVO_RECHAZO_TRSOLLIN`       varchar(255)  NULL DEFAULT NULL\'\r\n  \'       COMMENT \'\'Motivo si la linea se deniega (servida=0)\'\',\'\r\n  \'  `INSTANTE_MODIF`                timestamp     NOT NULL\'\r\n  \'       DEFAULT current_timestamp() ON UPDATE current_timestamp(),\'\r\n  \'  `INSTANTE_ALTA`                 timestamp     NOT NULL\'\r\n  \'       DEFAULT \'\'0000-00-00 00:00:00\'\',\'\r\n  \'  `USUARIO_ALTA`                  varchar(100)  NOT NULL,\'\r\n  \'  `USUARIO_MODIF`                 varchar(100)  NOT NULL,\'\r\n  \'  PRIMARY KEY (`NUMERO_TRSOL_TRSOLLIN`,`SERIE_TRSOL_TRSOLLIN`,\'\r\n  \'               `LINEA_TRSOLLIN`)\'\r\n  \') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @idx_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes_lineas\'\r\n     AND INDEX_NAME   = \'IDX_TRSOLLIN_SKU\'\r\n);\r\nSET @ddl := IF(@idx_exists = 0,\r\n  \'ALTER TABLE `fza_traspasos_solicitudes_lineas` \'\r\n  \'ADD INDEX `IDX_TRSOLLIN_SKU` (`CODIGO_UNIDAD_TRSOLLIN`)\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\n-- Columna MOTIVO_RECHAZO_TRSOLLIN: anadida despues de la creacion original,\r\n-- por eso va con guarda idempotente (sirve para BBDD ya existentes y para las\r\n-- nuevas). Guarda el motivo cuando se deniega una linea (cantidad servida = 0).\r\nSET @col_exists := (\r\n  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes_lineas\'\r\n     AND COLUMN_NAME  = \'MOTIVO_RECHAZO_TRSOLLIN\'\r\n);\r\nSET @ddl := IF(@col_exists = 0,\r\n  \'ALTER TABLE `fza_traspasos_solicitudes_lineas` \'\r\n  \'ADD COLUMN `MOTIVO_RECHAZO_TRSOLLIN` varchar(255) NULL DEFAULT NULL \'\r\n  \'COMMENT \'\'Motivo si la linea se deniega (servida=0)\'\' \'\r\n  \'AFTER `ESATENDIDA_TRSOLLIN`\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 3. Contador global de solicitudes de traspaso (TIPO_DOC = \'TS\')\r\n-- Lo consume inLibValoresAutomaticos.ObtenerSiguienteContador(\'TS\').\r\n-- Se siembra solo si no existe ya la fila global (\'TS\',\'-\',\'-\').\r\n-- ---------------------------------------------------------------------------\r\nINSERT INTO `fza_contadores`\r\n  (`TIPO_DOC_CON`, `EMPRESA_CON`, `SERIE_CON`, `CON`, `NUM_DIGITOS_CON`,\r\n   `ESACTIVO_CON`, `DEFAULT_CON`, `INSTANTE_ALTA`, `USUARIO_ALTA`,\r\n   `USUARIO_MODIF`)\r\nSELECT \'TS\', \'-\', \'-\', 0, 10, \'S\', \'S\', NOW(), \'SISTEMA\', \'SISTEMA\'\r\n WHERE NOT EXISTS (\r\n   SELECT 1 FROM `fza_contadores`\r\n    WHERE `TIPO_DOC_CON` = \'TS\'\r\n      AND `EMPRESA_CON` = \'-\'\r\n      AND `SERIE_CON` = \'-\');\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 4. Alinear la colacion de las tablas con la del resto del modelo\r\n--    (utf8mb4_spanish_ci). Si MariaDB las creo con su colacion por defecto\r\n--    (utf8mb4_uca1400_ai_ci), los JOIN/\'=\' contra fza_articulos_* fallan con\r\n--    \"Illegal mix of collations\". Solo se convierte si la tabla no esta ya\r\n--    en spanish_ci (idempotente).\r\n-- ---------------------------------------------------------------------------\r\nSET @col := (\r\n  SELECT TABLE_COLLATION FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\');\r\nSET @ddl := IF(@col IS NOT NULL AND @col <> \'utf8mb4_spanish_ci\',\r\n  \'ALTER TABLE `fza_traspasos_solicitudes` \'\r\n  \'CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @col := (\r\n  SELECT TABLE_COLLATION FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes_lineas\');\r\nSET @ddl := IF(@col IS NOT NULL AND @col <> \'utf8mb4_spanish_ci\',\r\n  \'ALTER TABLE `fza_traspasos_solicitudes_lineas` \'\r\n  \'CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci\',\r\n  \'SELECT 1\');\r\nPREPARE stmt FROM @ddl;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 5. Titulos de columna para el formateador (fza_config_campos), usados por\r\n--    el buscador de solicitudes abiertas (frmMtoSolicitudesSearch). Asi no se\r\n--    hardcodean captions: el buscador titula via oConfigCampos. Idempotente\r\n--    (INSERT ... WHERE NOT EXISTS por PK TABLA_OBJETIVO_CC+OBJETIVO_CC).\r\n-- ---------------------------------------------------------------------------\r\nINSERT INTO `fza_config_campos`\r\n  (`TABLA_OBJETIVO_CC`, `OBJETIVO_CC`, `TITULO_VISUAL_CC`,\r\n   `ANCHO_COLUMNA_CC`, `ORDEN_VISUAL_CC`, `VISIBLE_CC`)\r\nSELECT * FROM (SELECT\r\n  \'fza_traspasos_solicitudes\' AS t, \'NUMERO_TRSOL\' AS o, \'Número\' AS v,\r\n  90 AS a, 1 AS ord, \'S\' AS vis) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_config_campos`\r\n   WHERE TABLA_OBJETIVO_CC = \'fza_traspasos_solicitudes\'\r\n     AND OBJETIVO_CC = \'NUMERO_TRSOL\');\r\nINSERT INTO `fza_config_campos`\r\n  (`TABLA_OBJETIVO_CC`, `OBJETIVO_CC`, `TITULO_VISUAL_CC`,\r\n   `ANCHO_COLUMNA_CC`, `ORDEN_VISUAL_CC`, `VISIBLE_CC`)\r\nSELECT * FROM (SELECT\r\n  \'fza_traspasos_solicitudes\' AS t, \'SERIE_TRSOL\' AS o, \'Serie\' AS v,\r\n  60 AS a, 2 AS ord, \'S\' AS vis) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_config_campos`\r\n   WHERE TABLA_OBJETIVO_CC = \'fza_traspasos_solicitudes\'\r\n     AND OBJETIVO_CC = \'SERIE_TRSOL\');\r\nINSERT INTO `fza_config_campos`\r\n  (`TABLA_OBJETIVO_CC`, `OBJETIVO_CC`, `TITULO_VISUAL_CC`,\r\n   `ANCHO_COLUMNA_CC`, `ORDEN_VISUAL_CC`, `VISIBLE_CC`)\r\nSELECT * FROM (SELECT\r\n  \'fza_traspasos_solicitudes\' AS t, \'FECHA_TRSOL\' AS o,\r\n  \'Fecha / hora\' AS v, 165 AS a, 3 AS ord, \'S\' AS vis) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_config_campos`\r\n   WHERE TABLA_OBJETIVO_CC = \'fza_traspasos_solicitudes\'\r\n     AND OBJETIVO_CC = \'FECHA_TRSOL\');\r\nINSERT INTO `fza_config_campos`\r\n  (`TABLA_OBJETIVO_CC`, `OBJETIVO_CC`, `TITULO_VISUAL_CC`,\r\n   `ANCHO_COLUMNA_CC`, `ORDEN_VISUAL_CC`, `VISIBLE_CC`)\r\nSELECT * FROM (SELECT\r\n  \'fza_traspasos_solicitudes\' AS t, \'CODIGO_ALM_DESTINO_TRSOL\' AS o,\r\n  \'Solicitante\' AS v, 110 AS a, 4 AS ord, \'S\' AS vis) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_config_campos`\r\n   WHERE TABLA_OBJETIVO_CC = \'fza_traspasos_solicitudes\'\r\n     AND OBJETIVO_CC = \'CODIGO_ALM_DESTINO_TRSOL\');\r\nINSERT INTO `fza_config_campos`\r\n  (`TABLA_OBJETIVO_CC`, `OBJETIVO_CC`, `TITULO_VISUAL_CC`,\r\n   `ANCHO_COLUMNA_CC`, `ORDEN_VISUAL_CC`, `VISIBLE_CC`)\r\nSELECT * FROM (SELECT\r\n  \'fza_traspasos_solicitudes\' AS t, \'ESTADO_TRSOL\' AS o, \'Estado\' AS v,\r\n  90 AS a, 5 AS ord, \'S\' AS vis) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_config_campos`\r\n   WHERE TABLA_OBJETIVO_CC = \'fza_traspasos_solicitudes\'\r\n     AND OBJETIVO_CC = \'ESTADO_TRSOL\');\r\nINSERT INTO `fza_config_campos`\r\n  (`TABLA_OBJETIVO_CC`, `OBJETIVO_CC`, `TITULO_VISUAL_CC`,\r\n   `ANCHO_COLUMNA_CC`, `ORDEN_VISUAL_CC`, `VISIBLE_CC`)\r\nSELECT * FROM (SELECT\r\n  \'fza_traspasos_solicitudes\' AS t, \'LINEAS_PEND_TRSOL\' AS o,\r\n  \'Líneas pend.\' AS v, 90 AS a, 6 AS ord, \'S\' AS vis) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_config_campos`\r\n   WHERE TABLA_OBJETIVO_CC = \'fza_traspasos_solicitudes\'\r\n     AND OBJETIVO_CC = \'LINEAS_PEND_TRSOL\');\r\n-- Almacen ORIGEN: a quien pedi. Lo usa el historico \"Mis peticiones\" (F7),\r\n-- donde yo soy el destino. Mismo slot (orden 4) que el Solicitante, ya que\r\n-- nunca aparecen juntos en el mismo buscador.\r\nINSERT INTO `fza_config_campos`\r\n  (`TABLA_OBJETIVO_CC`, `OBJETIVO_CC`, `TITULO_VISUAL_CC`,\r\n   `ANCHO_COLUMNA_CC`, `ORDEN_VISUAL_CC`, `VISIBLE_CC`)\r\nSELECT * FROM (SELECT\r\n  \'fza_traspasos_solicitudes\' AS t, \'CODIGO_ALM_ORIGEN_TRSOL\' AS o,\r\n  \'Pedido a\' AS v, 110 AS a, 4 AS ord, \'S\' AS vis) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_config_campos`\r\n   WHERE TABLA_OBJETIVO_CC = \'fza_traspasos_solicitudes\'\r\n     AND OBJETIVO_CC = \'CODIGO_ALM_ORIGEN_TRSOL\');\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 6. Perfil del buscador de solicitudes (frmMtoSolicitudesSearch): activar\r\n--    oApplyWidth para que aplique anchos/orden de columna desde el perfil\r\n--    (igual que el resto de buscadores). Se siembra para el grupo \'Todos\'.\r\n--    Idempotente (PK USUARIO_GRUPO+KEY+SUBKEY; INSERT ... WHERE NOT EXISTS).\r\n-- ---------------------------------------------------------------------------\r\nINSERT INTO `fza_usuarios_perfiles`\r\n  (`USUARIO_GRUPO_USUPER`, `KEY_USUPER`, `SUBKEY_USUPER`, `VALUE_USUPER`,\r\n   `INSTANTE_ALTA`, `USUARIO_ALTA`, `USUARIO_MODIF`)\r\nSELECT * FROM (SELECT\r\n  \'Todos\' AS g, \'frmMtoSolicitudesSearch\' AS k, \'oApplyWidth\' AS s,\r\n  \'True\' AS v, NOW() AS ia, \'SISTEMA\' AS ua, \'SISTEMA\' AS um) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_usuarios_perfiles`\r\n   WHERE USUARIO_GRUPO_USUPER = \'Todos\'\r\n     AND KEY_USUPER = \'frmMtoSolicitudesSearch\'\r\n     AND SUBKEY_USUPER = \'oApplyWidth\');\r\nINSERT INTO `fza_usuarios_perfiles`\r\n  (`USUARIO_GRUPO_USUPER`, `KEY_USUPER`, `SUBKEY_USUPER`, `VALUE_USUPER`,\r\n   `INSTANTE_ALTA`, `USUARIO_ALTA`, `USUARIO_MODIF`)\r\nSELECT * FROM (SELECT\r\n  \'Todos\' AS g, \'frmMtoSolicitudesSearch\' AS k,\r\n  \'cxGrdDBTabPrin__oApplyWidth\' AS s, \'True\' AS v, NOW() AS ia,\r\n  \'SISTEMA\' AS ua, \'SISTEMA\' AS um) x\r\n WHERE NOT EXISTS (SELECT 1 FROM `fza_usuarios_perfiles`\r\n   WHERE USUARIO_GRUPO_USUPER = \'Todos\'\r\n     AND KEY_USUPER = \'frmMtoSolicitudesSearch\'\r\n     AND SUBKEY_USUPER = \'cxGrdDBTabPrin__oApplyWidth\');\r\n','2026-08-11 05:18:44','2026-08-11 05:18:44','Administrador','Administrador'),
('623','traspasos_solicitudes_fecha_hora','-- =============================================================================\r\n-- Solicitudes de traspaso: conservar fecha y hora de la solicitud\r\n-- =============================================================================\r\n-- FECHA_TRSOL se creo originalmente como date. Se convierte a datetime para\r\n-- que las nuevas solicitudes puedan guardar el instante mediante\r\n-- CURRENT_TIMESTAMP.\r\n--\r\n-- Las solicitudes existentes que siguen a las 00:00:00 conservan la fecha\r\n-- funcional de FECHA_TRSOL y recuperan solo la hora desde INSTANTE_ALTA.\r\n-- INSTANTE_ALTA se usa exclusivamente para este backfill historico.\r\n-- =============================================================================\r\n\r\nSET @sExisteTabla := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n);\r\n\r\nSET @sTipoFecha := (\r\n  SELECT LOWER(DATA_TYPE)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND COLUMN_NAME  = \'FECHA_TRSOL\'\r\n);\r\n\r\nSET @sDefaultFecha := (\r\n  SELECT LOWER(COALESCE(COLUMN_DEFAULT, \'\'))\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND COLUMN_NAME  = \'FECHA_TRSOL\'\r\n);\r\n\r\nSET @sSql := IF(\r\n  @sExisteTabla > 0\r\n  AND @sTipoFecha IS NOT NULL\r\n  AND (@sTipoFecha = \'date\'\r\n       OR (@sTipoFecha = \'datetime\'\r\n           AND @sDefaultFecha NOT LIKE \'%current_timestamp%\')),\r\n  \'ALTER TABLE fza_traspasos_solicitudes\r\n     MODIFY COLUMN FECHA_TRSOL datetime NULL DEFAULT CURRENT_TIMESTAMP\',\r\n  \'SELECT \'\'FECHA_TRSOL ya esta normalizada o no existe\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sTipoFechaActual := (\r\n  SELECT LOWER(DATA_TYPE)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND COLUMN_NAME  = \'FECHA_TRSOL\'\r\n);\r\n\r\nSET @sExisteInstanteAlta := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traspasos_solicitudes\'\r\n     AND COLUMN_NAME  = \'INSTANTE_ALTA\'\r\n);\r\n\r\nSET @sSql := IF(\r\n  @sExisteTabla > 0\r\n  AND @sTipoFechaActual = \'datetime\'\r\n  AND @sExisteInstanteAlta > 0,\r\n  \'UPDATE fza_traspasos_solicitudes\r\n      SET FECHA_TRSOL = TIMESTAMP(\r\n            DATE(FECHA_TRSOL), TIME(INSTANTE_ALTA))\r\n    WHERE FECHA_TRSOL IS NOT NULL\r\n      AND INSTANTE_ALTA IS NOT NULL\r\n      AND CAST(FECHA_TRSOL AS CHAR) NOT LIKE \'\'0000-00-00%\'\'\r\n      AND CAST(INSTANTE_ALTA AS CHAR) NOT LIKE \'\'0000-00-00%\'\'\r\n      AND SUBSTRING(CAST(FECHA_TRSOL AS CHAR), 12, 8) = \'\'00:00:00\'\'\r\n      AND SUBSTRING(CAST(INSTANTE_ALTA AS CHAR), 12, 8) <> \'\'00:00:00\'\'\',\r\n  \'SELECT \'\'No se puede recuperar la hora historica\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteConfigCampos := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_config_campos\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteConfigCampos > 0,\r\n  \'UPDATE fza_config_campos\r\n      SET TITULO_VISUAL_CC = \'\'Fecha / hora\'\',\r\n          ANCHO_COLUMNA_CC = 165\r\n    WHERE TABLA_OBJETIVO_CC = \'\'fza_traspasos_solicitudes\'\'\r\n      AND OBJETIVO_CC = \'\'FECHA_TRSOL\'\'\r\n      AND (COALESCE(TITULO_VISUAL_CC, \'\'\'\') <> \'\'Fecha / hora\'\'\r\n           OR COALESCE(ANCHO_COLUMNA_CC, -1) <> 165)\',\r\n  \'SELECT \'\'No existe fza_config_campos\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteTraducciones := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.TABLES\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_traducciones\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteTraducciones > 0,\r\n  \'UPDATE fza_traducciones\r\n      SET TEXTO_TRAD = CASE IDIOMA_TRAD\r\n            WHEN \'\'es-ES\'\' THEN \'\'Fecha / hora\'\'\r\n            WHEN \'\'en-GB\'\' THEN \'\'Date / time\'\'\r\n            WHEN \'\'ca-ES\'\' THEN \'\'Data / hora\'\'\r\n          END,\r\n          INSTANTE_MODIF = CURRENT_TIMESTAMP,\r\n          USUARIO_MODIF = \'\'SISTEMA\'\'\r\n    WHERE CLAVE_TRAD = \'\'inLibMsgCaja.SCaptionColFechaSolicitud\'\'\r\n      AND IDIOMA_TRAD IN (\'\'es-ES\'\', \'\'en-GB\'\', \'\'ca-ES\'\')\r\n      AND TEXTO_TRAD <> CASE IDIOMA_TRAD\r\n            WHEN \'\'es-ES\'\' THEN \'\'Fecha / hora\'\'\r\n            WHEN \'\'en-GB\'\' THEN \'\'Date / time\'\'\r\n            WHEN \'\'ca-ES\'\' THEN \'\'Data / hora\'\'\r\n          END\',\r\n  \'SELECT \'\'No existe fza_traducciones\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n','2026-08-11 05:29:19','2026-08-11 05:29:19','Administrador','Administrador');
