('Administrador','frmPrintEtiqArt','frxrprt1_Luis','Luis',NULL,NULL,'<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"no\"?>\r\n<TfrxReport Version=\"2025.1.1\" DotMatrixReport=\"False\" IniFile=\"\\Software\\Fast Reports\" PreviewOptions.Buttons=\"4095\" PreviewOptions.Zoom=\"1\" PrintOptions.Printer=\"Por defecto\" PrintOptions.PrintOnSheet=\"0\" ReportOptions.CreateDate=\"42481,6346757407\" ReportOptions.Description.Text=\"\" ReportOptions.LastChange=\"46234,3359674421\" ScriptLanguage=\"PascalScript\" ScriptText.Text=\"function HexNibble(c: Char): Integer;&#13;&#10;begin&#13;&#10;  if (c &#62;= \'0\') and (c &#60;= \'9\') then&#13;&#10;    Result := Ord(c) - Ord(\'0\')&#13;&#10;  else if (c &#62;= \'A\') and (c &#60;= \'F\') then&#13;&#10;    Result := Ord(c) - Ord(\'A\') + 10&#13;&#10;  else if (c &#62;= \'a\') and (c &#60;= \'f\') then&#13;&#10;    Result := Ord(c) - Ord(\'a\') + 10&#13;&#10;  else&#13;&#10;    Result := -1;&#13;&#10;end;&#13;&#10;&#13;&#10;function HexToColor(sHex: String): Integer;&#13;&#10;var&#13;&#10;  iOff, R, G, B, n0, n1, n2, n3, n4, n5: Integer;&#13;&#10;begin&#13;&#10;  Result := -1;&#13;&#10;  sHex := Trim(sHex);&#13;&#10;  if Length(sHex) &#60; 6 then Exit;&#13;&#10;  if Copy(sHex, 1, 1) = \'#\' then iOff := 1 else iOff := 0;&#13;&#10;  if Length(sHex) &#60; 6 + iOff then Exit;&#13;&#10;  n0 := HexNibble(sHex[iOff + 1]);&#13;&#10;  n1 := HexNibble(sHex[iOff + 2]);&#13;&#10;  n2 := HexNibble(sHex[iOff + 3]);&#13;&#10;  n3 := HexNibble(sHex[iOff + 4]);&#13;&#10;  n4 := HexNibble(sHex[iOff + 5]);&#13;&#10;  n5 := HexNibble(sHex[iOff + 6]);&#13;&#10;  if (n0 &#60; 0) or (n1 &#60; 0) or (n2 &#60; 0) or (n3 &#60; 0) or (n4 &#60; 0) or (n5 &#60; 0) then Exit;&#13;&#10;  R := n0 * 16 + n1;&#13;&#10;  G := n2 * 16 + n3;&#13;&#10;  B := n4 * 16 + n5;&#13;&#10;  Result := (B shl 16) or (G shl 8) or R;&#13;&#10;end;&#13;&#10;&#13;&#10;procedure EtiqColorOnBeforePrint(Sender: TfrxComponent);&#13;&#10;var&#13;&#10;  sHex: String;&#13;&#10;  c, R, G, B, Y: Integer;&#13;&#10;  m: TfrxMemoView;&#13;&#10;begin&#13;&#10;  m := TfrxMemoView(Sender);&#13;&#10;  sHex := &#60;EtiquetasArt.&#34;HEX_ATR_CO&#34;&#62;;&#13;&#10;  c := HexToColor(sHex);&#13;&#10;  if c &#60; 0 then begin&#13;&#10;    m.Color := $00FFFFFF;&#13;&#10;    m.Font.Color := $00000000;&#13;&#10;    Exit;&#13;&#10;  end;&#13;&#10;  m.Color := c;&#13;&#10;  R := c and $FF;&#13;&#10;  G := (c shr 8) and $FF;&#13;&#10;  B := (c shr 16) and $FF;&#13;&#10;  Y := (R * 299 + G * 587 + B * 114) div 1000;&#13;&#10;  if Y &#60; 140 then&#13;&#10;    m.Font.Color := $00FFFFFF&#13;&#10;  else&#13;&#10;    m.Font.Color := $00000000;&#13;&#10;end;&#13;&#10;&#13;&#10;begin&#13;&#10;end.\">\r\n  <Datasets>\r\n    <item DataSet=\"dmArticulos.fxdsEtiquetasArt\" DataSetName=\"EtiquetasArt\"/>\r\n  </Datasets>\r\n  <TfrxDataPage Name=\"Data\" HGuides.Text=\"\" VGuides.Text=\"\" Height=\"1000\" Left=\"0\" Top=\"0\" Width=\"1000\"/>\r\n  <TfrxReportPage Name=\"Page1\" HGuides.Text=\"\" VGuides.Text=\"\" PaperWidth=\"210\" PaperHeight=\"297\" PaperSize=\"9\" LeftMargin=\"0\" RightMargin=\"0\" TopMargin=\"4,5\" BottomMargin=\"4,5\" Columns=\"2\" ColumnWidth=\"105\" ColumnPositions.Text=\"0&#13;&#10;105\" Frame.Typ=\"0\" MirrorMode=\"0\">\r\n    <TfrxMasterData Name=\"MasterData1\" FillType=\"ftBrush\" FillGap.Top=\"0\" FillGap.Left=\"0\" FillGap.Bottom=\"0\" FillGap.Right=\"0\" Frame.Typ=\"0\" Height=\"181,41744\" Left=\"0\" Top=\"18,89765\" Width=\"396,85065\" ColumnWidth=\"0\" ColumnGap=\"0\" DataSet=\"dmArticulos.fxdsEtiquetasArt\" DataSetName=\"EtiquetasArt\" RowCount=\"0\">\r\n      <TfrxMemoView Name=\"EtiqRefProv\" AllowVectorExport=\"True\" Left=\"210\" Top=\"6\" Width=\"180\" Height=\"14\" DataField=\"REF_PROVEEDOR\" DataSet=\"dmArticulos.fxdsEtiquetasArt\" DataSetName=\"EtiquetasArt\" Font.Charset=\"1\" Font.Color=\"0\" Font.Height=\"-14\" Font.Name=\"Arial\" Font.Style=\"0\" Frame.Typ=\"0\" HAlign=\"haRight\" ParentFont=\"False\" Text=\"[EtiquetasArt.&#