--
-- Table structure for table `fza_facturas_compra`
--

DROP TABLE IF EXISTS `fza_facturas_compra`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `fza_facturas_compra` (
  `NUMERO_FACC` varchar(20) NOT NULL,
  `SERIE_FACC` varchar(20) NOT NULL,
  `FECHA_FACC` date DEFAULT NULL COMMENT 'Fecha de la factura del proveedor',
  `FECHA_VALOR_FACC` date DEFAULT NULL COMMENT 'Fecha valor / contable (legacy FechaValor)',
  `ESTADO_FACC` varchar(20) DEFAULT 'ABIERTA' COMMENT 'ABIERTA, CERRADA, CONTABILIZADA, PAGADA, CANCELADA',
  `DOC_EXTERNO_FACC` varchar(50) DEFAULT NULL COMMENT 'Nro de factura segun el proveedor (legacy DocExterno)',
  `REF_PROVEEDOR_FACC` varchar(50) DEFAULT NULL,
  `CODIGO_EMP_FACC` varchar(8) DEFAULT NULL,
  `RAZON_SOCIAL_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `NIF_EMPRESA_FACC` varchar(50) DEFAULT NULL,
  `MOVIL_EMPRESA_FACC` varchar(40) DEFAULT NULL,
  `EMAIL_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `POBLACION_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_FACC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_FACC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_EMPRESA_FACC` varchar(15) DEFAULT NULL,
  `CODIGO_PRV_FACC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_proveedores',
  `RAZON_SOCIAL_PRV_FACC` varchar(200) DEFAULT NULL,
  `NIF_PRV_FACC` varchar(50) DEFAULT NULL,
  `MOVIL_PRV_FACC` varchar(40) DEFAULT NULL,
  `EMAIL_PRV_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION1_PRV_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION2_PRV_FACC` varchar(200) DEFAULT NULL,
  `POBLACION_PRV_FACC` varchar(200) DEFAULT NULL,
  `PROVINCIA_PRV_FACC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_PRV_FACC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_PRV_FACC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_PRV_FACC` varchar(15) DEFAULT NULL,
  `CODIGO_ALM_FACC` varchar(10) DEFAULT NULL,
  `CODIGO_IVA_FACC` varchar(20) DEFAULT NULL,
  `ESIVA_RECARGO_COMPRAS_FACC` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_INTRACOMUNITARIO_FACC` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = IVA exento por proveedor intracomunitario',
  `PORCENTAJE_IVAN_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAN_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAN_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REN_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REN_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAR_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAR_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAR_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RER_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RER_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAS_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAS_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAS_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RES_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RES_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAE_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAE_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAE_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REE_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REE_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_DTO_COMERCIAL_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_DTO_COMERCIAL_FACC` decimal(18,6) DEFAULT NULL,
