--
-- Table structure for table `fza_facturas_lineas`
--

DROP TABLE IF EXISTS `fza_facturas_lineas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `fza_facturas_lineas` (
  `NUMERO_FAC_FACLIN` varchar(20) NOT NULL,
  `SERIE_FAC_FACLIN` varchar(20) NOT NULL,
  `CODIGO_EMP_FACLIN` varchar(8) DEFAULT NULL,
  `LINEA_FACLIN` varchar(4) NOT NULL,
  `CODIGO_ART_FACLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_FACLIN` varchar(50) DEFAULT NULL,
  `LOTE_FACLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_FACLIN` date DEFAULT NULL,
  `CODIGO_FAM_FACLIN` varchar(20) DEFAULT NULL,
  `NOMBRE_FAM_FACLIN` varchar(200) DEFAULT NULL,
  `PRECIO_ULT_COMPRA_FACLIN` decimal(19,6) DEFAULT NULL,
  `CODIGO_PRV_FACLIN` varchar(20) DEFAULT NULL,
  `RAZON_SOCIAL_PROVEEDOR_FACLIN` varchar(200) DEFAULT NULL,
  `ESPROVEEDORPRINCIPAL_FACLIN` varchar(1) DEFAULT NULL,
  `FECHA_ENTREGA_FACLIN` datetime DEFAULT NULL,
  `TIPO_ARTICULO_FACLIN` varchar(10) DEFAULT 'ESTANDAR' COMMENT 'ESTANDAR=Físico (Control Stock), SERVICIO=Intangible (Sin Stock), KIT=Pack',
  `TIPO_CANTIDAD_ARTICULO_FACLIN` varchar(20) DEFAULT 'Uds',
  `CANTIDAD_FACLIN` decimal(19,6) DEFAULT 1.000000,
  `DESCRIPCION_ARTICULO_FACLIN` varchar(100) DEFAULT NULL,
  `DESCRIPCION_VARIACION_FACLIN` varchar(200) DEFAULT NULL,
  `CODIGO_TAR_FACLIN` varchar(10) DEFAULT NULL,
  `ESIMP_INCL_TARIFA_FACLIN` varchar(1) DEFAULT 'S',
  `PRECIO_SALIDA_FACLIN` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_DTO_FACLIN` decimal(19,6) DEFAULT NULL,
  `PRECIO_DTO_FACLIN` decimal(19,6) DEFAULT NULL,
  `PRECIO_VENTA_SIVA_ARTICULO_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `TIPO_IVA_ARTICULO_FACLIN` varchar(2) DEFAULT 'N',
  `PORCENTAJE_IVA_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_VENTA_CIVA_ARTICULO_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_FAC_SIVA_FACLIN` decimal(19,6) DEFAULT NULL,
  `CODIGO_VENDEDOR_FACLIN` varchar(10) DEFAULT NULL COMMENT 'Usuario que se lleva la comisión',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `CODIGO_ALM_FACLIN` varchar(10) DEFAULT NULL,
  `CODIGO_CAJA_FACLIN` varchar(10) DEFAULT NULL,
  `NUMERO_OPERACION_FACLIN` varchar(20) DEFAULT NULL,
  `NUMERO_MOV_FACLIN` varchar(20) DEFAULT NULL,
  `ATTR1_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `NUM_ATRIBUTOS_FACLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Atributos requeridos del articulo',
  PRIMARY KEY (`NUMERO_FAC_FACLIN`,`SERIE_FAC_FACLIN`,`LINEA_FACLIN`),
  KEY `FT_FACLIN_DESC` (`DESCRIPCION_ARTICULO_FACLIN`),
  KEY `IDX_FACLIN_OPERACION` (`CODIGO_EMP_FACLIN`,`CODIGO_ALM_FACLIN`,`CODIGO_CAJA_FACLIN`,`NUMERO_OPERACION_FACLIN`),
  KEY `IDX_FACLIN_UNIDAD` (`CODIGO_UNIDAD_FACLIN`),
  KEY `IDX_FAC_LIN_ARTICULO` (`CODIGO_ART_FACLIN`,`SERIE_FAC_FACLIN`),
  KEY `IDX_FAC_LIN_FAMILIA` (`CODIGO_FAM_FACLIN`),
  KEY `IDX_FACLIN_NUMMOV` (`NUMERO_MOV_FACLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
