/*!50003 SET collation_connection  = utf8mb3_uca1400_ai_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_ADD_INDEX_IF_NOT_EXISTS`(IN `p_tabla` VARCHAR(64),    /* Nombre de la tabla destino, sin backticks */
    IN `p_indice` VARCHAR(64),       /* Nombre del indice a crear (convencion IDX_<SUF>_<col>) */
    IN `p_columnas` VARCHAR(1000))
BEGIN
    /* Crea un indice si no existe ya en la BBDD actual. Idempotente y
       seguro de re-ejecutar. Pensado para migraciones de rendimiento. */
    IF NOT EXISTS (
        SELECT 1
          FROM information_schema.statistics
         WHERE table_schema = DATABASE()
           AND table_name   = p_tabla
           AND index_name   = p_indice
    ) THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_tabla,
                          '` ADD INDEX `', p_indice,
                          '` (', p_columnas, ')');
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END
;;
DELIMITER ;
