CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_CREAR_ACTUALIZAR_KEY`(
    IN pUSUARIO       varchar(200),
    IN pKEY           varchar(100),
    IN pSUBKEY        varchar(100),
    IN pVALUE         varchar(200),
    IN pVALUE_TEXT    text,
    IN pUSUARIO_MODIF varchar(100)
)
BEGIN

    /* Manejo de errores para asegurar la consistencia */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION 
    kk: BEGIN
        ROLLBACK;
        RESIGNAL;
    END kk;
    START TRANSACTION;    
    /* Comprobamos si el registro existe */
    IF ( EXISTS(
             SELECT 1
             FROM `fza_usuarios_perfiles`
             WHERE `USUARIO_GRUPO_USUPER` = pUSUARIO
               AND `KEY_USUPER`           = pKEY 
               AND `SUBKEY_USUPER`        = pSUBKEY 
        )) THEN
        
        UPDATE `fza_usuarios_perfiles`
        SET `VALUE_USUPER`      = pVALUE,
            `VALUE_TEXT_USUPER` = pVALUE_TEXT,
            `USUARIO_MODIF`        = pUSUARIO_MODIF
        WHERE `USUARIO_GRUPO_USUPER` = pUSUARIO
          AND `KEY_USUPER`           = pKEY 
          AND `SUBKEY_USUPER`        = pSUBKEY;
          
    ELSE
    
            `USUARIO_GRUPO_USUPER`, 
            `KEY_USUPER`, 
            `SUBKEY_USUPER`, 
            `VALUE_USUPER`, 
            `VALUE_TEXT_USUPER`, 
            `INSTANTE_ALTA`, 
            `USUARIO_ALTA`, 
            `USUARIO_MODIF`
        ) VALUES (
            pUSUARIO,
            pKEY,
            pSUBKEY,
            pVALUE,
            pVALUE_TEXT,
            CURRENT_TIMESTAMP,
            pUSUARIO_MODIF,
            pUSUARIO_MODIF
        );
        
    END IF;
    
    COMMIT;
    
END
;;
