)
BEGIN   
    DECLARE contadorped varchar(200);
    DECLARE pFecha date;

    /* Manejo de errores para asegurar la consistencia */    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION 
    kk: BEGIN        
        ROLLBACK;
        RESIGNAL;
    END kk;

    START TRANSACTION;
    
