    CALL PRC_GET_NEXT_CONT_FACT_SERIE(pidseriefacturaabono, 'FC', pidcodigo_empresa, pUSUARIO, contadorped);   
    
    /* Asignación limpia sin DATE_FORMAT innecesario */
