CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_CREAR_FACTURA_DUPLICADA`(
    IN pidseriefactura      varchar(200),
    IN pidnumfactura        varchar(200),
    IN pidseriefacturaabono varchar(200),
